INSERT INTO public.lesson_content (lesson_key, course_id, title, content_html, updated_at)
VALUES
('kurmanji-course-1-lesson-01.html','kurmanji-course-1','ناسینی کورمانجی و چوارچێوەی ڕێنووسی لاتینی','<section class="klesson-card"><h2>١. کورمانجی چییە؟</h2><p>کورمانجی (Kurmancî) یەکێکە لە شێوە و ڕێڕەوە زمانییە سەرەکییەکانی کوردی. لە زۆرێک لە بەکارهێنانە نووسراوە هاوچەرخەکاندا، کورمانجی بە ئەلفبێی لاتینیی هاوار دەنووسرێت. ئەم وانەیە ئەم سیستەمەی نووسین دەکاتە بابەتی سەرەکی؛ بەڵام نابێت ئەلفبێی نووسین لە خودی زمان یان لە هەموو تایبەتمەندییە دەنگییەکانی جیاوازییە زمانییەکان یەکسان بگیرێت.</p></section>
<section class="klesson-card"><h2>٢. جیاوازیی زمان، ئەلفبێ و ڕێنووس</h2><ul><li><strong>زمان:</strong> سیستەمی گشتیی پەیوەندی و ڕێکخستنی زمانییە.</li><li><strong>ئەلفبێ:</strong> کۆمەڵە نیشانەی نووسینە کە بۆ نووسینی زمان بەکاردێن.</li><li><strong>ڕێنووس:</strong> ڕێساکانی نووسینی وشە و بەکارهێنانی نیشانەکانی نووسینە.</li></ul><p>لە فێربونی کورمانجی‌دا، ناسینی پیتەکان پێشەنگییەکی گرنگە؛ بەڵام تەنیا زانینی ناوی پیتەکان بەس نییە. فێرخواز دەبێت فۆڕمی نووسراو، خوێندنەوەی باو و شوێنی پیتەکان لە وشەدا بە یەکەوە فێرببێت.</p></section>
<section class="klesson-card"><h2>٣. سنووری ڕێڕەوی ئەم کۆرسە</h2><p>کۆرسی یەکەم لە ٢٦ وانەدا لە ناساندنی سیستەمی نووسینەوە دەگاتە خوێندنەوە و نووسینی وشە و ڕستەی سادە. بابەتەکانی مۆرفۆلۆجی و ڕێزمان بە شێوەیەکی ڕێک‌خراوتر لە کۆرسی دووەمدا دەخوێندرێنەوە.</p><div class="klesson-note">تێبینیی زانستی: کورمانجی لە ناوچە و کۆمەڵگە جیاوازەکاندا هەندێک جیاوازیی دەربڕین و بەکارهێنانی هەیە. لە وانەکانی داهاتوودا نموونەکان بە پشت‌بەستن بە سەرچاوەی دیاریکراو دەخرێنەڕوو؛ نابێت شێوەیەکی تایبەت بە هەموو بەکارهێنانەکان بگشتێندرێت.</div></section>
<section class="klesson-card"><h2>٤. پێداچوونەوە</h2><ol><li>جیاوازی نێوان ئەلفبێ و ڕێنووس چییە؟</li><li>بۆچی پێویستە سیستەمی نووسین لە خودی زمان جیا بکرێتەوە؟</li><li>ئەم کۆرسە چی دەگرێتەوە و بابەتە وردترەکانی ڕێزمان لە کوێ دەخوێندرێنەوە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. DOI: 10.1515/9783110421682-004.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. سەرچاوەی ڕێزمان و خوێندنەوەی کورمانجی.</li></ol><p class="klesson-note">ئەم دوو سەرچاوەیە بۆ چوارچێوەی گشتیی بابەتەکە دانراون؛ ژمارەی لاپەڕە نەنووسراوە، چونکە لەم قۆناغەدا پشتڕاست نەکراوەتەوە. پێش بڵاوکردنەوەی گشتی، زانیاریی تەواوی چاپ و بەش/لاپەڕەی پەیوەندیدار دەبێت لە خودی سەرچاوەکاندا بپشکنرێت.</p></section>',now()),
  ('kurmanji-course-1-lesson-02.html','kurmanji-course-1','ئەلفبێی هاوار و ٣١ پیتەکەی','<section class="klesson-card"><h2>١. ڕیزبەندی ئەلفبێ</h2><p>لە ڕێنووسی لاتینیی باوی کورمانجی، ئەلفبێکە ٣١ پیت لەخۆ دەگرێت. ئەم ڕیزبەندییە بۆ ناسینەوە و ڕێکخستنی وشەکان گرنگە:</p><div class="klesson-alphabet" aria-label="ئەلفبێی کورمانجی"><span>A</span><span>B</span><span>C</span><span>Ç</span><span>D</span><span>E</span><span>Ê</span><span>F</span><span>G</span><span>H</span><span>I</span><span>Î</span><span>J</span><span>K</span><span>L</span><span>M</span><span>N</span><span>O</span><span>P</span><span>Q</span><span>R</span><span>S</span><span>Ş</span><span>T</span><span>U</span><span>Û</span><span>V</span><span>W</span><span>X</span><span>Y</span><span>Z</span></div><p class="klesson-note">تێبینی: پیتەکانی ئەم ئەلفبێیە بە ڕێنووسی لاتینیی کورمانجی پەیوەستن. نابێت نیشانەی پیتەکان لە نووسینی کوردی بە ئەلفبێی عەرەبی یان لە سیستەمەکانی دیکەدا بە هەمان شێوە لێک بدرێنەوە.</p></section>
<section class="klesson-card"><h2>٢. پیتەکانی نیشانەدار</h2><ul><li><strong>Ç / ç</strong></li><li><strong>Ê / ê</strong></li><li><strong>Î / î</strong></li><li><strong>Ş / ş</strong></li><li><strong>Û / û</strong></li></ul><p>ئەم نیشانانە بەشێکن لە شێوەی نووسینی پیتەکە؛ لە نووسینی فەرمی‌دا نابێت بە پیتی بێ‌نیشانە بگۆڕدرێن، چونکە جیاوازیی ڕێنووسی دەهێننە ئاراوە. پیتەکانی Q، W و Xیش لە ئەلفبێی لاتینیی کورمانجی بەکاردێن.</p></section>
<section class="klesson-card"><h2>٣. پیت و دەنگ یەک شت نین</h2><p>پیت نیشانەی نووسراوە؛ دەنگ ئەو یەکەیە کە لە قسەکردندا دەبیسترێت. پەیوەندیی نێوان پیت و دەنگ بابەتێکی گرنگی فێربونی ڕێنووسە، بەڵام نابێت بە بێ پشکنینی دەنگییەوە وا دابنرێت کە هەر پیتێک لە هەموو وشە و شێوەزارێکدا تەنیا یەک دەنگی هەیە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ئەلفبێکە بە ڕیزبەندییەوە بخوێنەوە و بنووسە.</li><li>پیتە نیشانەدارەکان لە لیستەکەدا دیاری بکە.</li><li>بۆچی Ç و C، یان Ş و S، لە نووسینی فەرمی‌دا نابێت بە یەک شت دابنرێن؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>.</li></ol><p class="klesson-note">سەرچاوەکان بۆ چوارچێوەی گشتیی زمان و ڕێنووس دانراون. بۆ وەشانی کۆتایی، دەبێت هەر نموونەیەکی ورد بە چاپی سەرچاوەی ڕێنووسەکەوە بگونجێندرێت.</p></section>',now()),
  ('kurmanji-course-1-lesson-03.html','kurmanji-course-1','ڤاوڵەکان و نیشانەنووسییان','<section class="klesson-card"><h2>١. هەشت پیتی ڤاوڵ</h2><p>لە ڕێنووسی لاتینیی باوی کورمانجی، هەشت پیتی ڤاوڵ هەن:</p>
<table class="klesson-table"><thead><tr><th>پیت</th><th>تێبینیی ڕێنووسی</th><th>نموونە</th><th>واتا</th></tr></thead><tbody>
<tr><td>A a</td><td>پیتی ڤاوڵ</td><td>qaz</td><td>قاز</td></tr>
<tr><td>E e</td><td>جیاوازە لە Ê</td><td>belg</td><td>گەڵا</td></tr>
<tr><td>Ê ê</td><td>پیتی جیاواز بە نیشانەی ^</td><td>lêv</td><td>لێو</td></tr>
<tr><td>I i</td><td>جیاوازە لە Î</td><td>dil</td><td>دڵ</td></tr>
<tr><td>Î î</td><td>پیتی جیاواز بە نیشانەی ^</td><td>hîn</td><td>هێشتا</td></tr>
<tr><td>O o</td><td>پیتی ڤاوڵ</td><td>nod</td><td>نەوەد</td></tr>
<tr><td>U u</td><td>جیاوازە لە Û</td><td>qul</td><td>کون</td></tr>
<tr><td>Û û</td><td>پیتی جیاواز بە نیشانەی ^</td><td>bûz</td><td>سەهۆڵ</td></tr>
</tbody></table>
<p class="klesson-note">نموونەکان و واتاکانیان بە پشت‌بەستن بە خشتەی ڕێنووس و دەنگی کورمانجی لە سەرچاوەی زانکۆی ئەریزۆنا هەڵبژێردراون؛ لە بەکارهێنانی ڕۆژانەدا دەتوانێت هەندێک جیاوازیی شێوەزار هەبێت.</p></section>
<section class="klesson-card"><h2>٢. نیشانەی ^ بێ‌واتا نییە</h2><p>لە نووسینی کورمانجی، <strong>ê</strong> لە <strong>e</strong>، <strong>î</strong> لە <strong>i</strong>، و <strong>û</strong> لە <strong>u</strong> جیاوازن. بۆیە لە فێربون و نووسینی وشەکاندا پێویستە نیشانەکە بە وردی بپارێزرێت. گۆڕینی پیتێک بە پیتێکی هاوشێوە، دەتوانێت شێوەی وشە بگۆڕێت یان ڕێنووسەکە نادروست بکات.</p><p>لە ڕووی دەنگناسییەوە، سەرچاوەکان جیاوازیی دەنگیی نێوان ئەم پیتانە بە شێوەی IPA ڕوون دەکەنەوە؛ بەڵام باشترە فێرخواز تەنیا لەسەر هاوشێوەیی دەنگەکان لە زمانێکی دیکەوە بڕیار نەدات، چونکە هاوتاکردنەوەی دەنگ بە زمانی ئینگلیزی یان کوردیی ناوەندی تەواو و ورد نییە.</p></section>
<section class="klesson-card"><h2>٣. ڕاهێنان</h2><ol><li>هەشت پیتی ڤاوڵ بە پیتی گەورە و بچووک بنووسە.</li><li>جیاوازیی نووسینی e/ê، i/î و u/û دیاری بکە.</li><li>وشەکانی qaz، belg، lêv، dil، hîn، nod، qul و bûz بخوێنەوە و نیشانەی پیتەکان بپارێزە.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a> (خشتەی ڤاوڵ و نموونەی وشەکان).</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-04.html','kurmanji-course-1','کۆنسۆنەنتەکان و پەیوەندییان بە نووسینەوە','<section class="klesson-card"><h2>١. کۆنسۆنەنت چییە؟</h2><p>کۆنسۆنەنت (consonant) دەنگێکە کە لە دروستبوونیدا هەوا لە ڕێگای دەمدا بە بەربەستێک یان تەنگەبەرێک ڕووبەڕوو دەبێتەوە. لە نووسینی کورمانجی، پیتەکانی ئەلفبێ بە پێی ڕێنووسی لاتینی بەکاردێن؛ بەڵام پیت و دەنگ یەک شت نین، چونکە پەیوەندیی نێوانیان لە هەموو شێوەزارەکاندا هەمیشە یەکسان نییە.</p></section>
<section class="klesson-card"><h2>٢. پیتە کۆنسۆنەنتەکان</h2><p>لە ئەلفبێی ٣١ پیتی کورمانجی، ئەمانە وەک پیتی کۆنسۆنەنت بەکاردێن:</p><table class="klesson-table"><thead><tr><th>پیت</th><th>تێبینیی خوێندنەوە</th></tr></thead><tbody>
<tr><td>B b</td><td>کۆنسۆنەنتی دەنگدار</td></tr><tr><td>C c</td><td>لە خشتەی IPAدا بە /d͡ʒ/ نوێنەرایەتی دەکرێت</td></tr><tr><td>Ç ç</td><td>/t͡ʃ/</td></tr><tr><td>D d</td><td>/d/</td></tr><tr><td>F f</td><td>/f/</td></tr><tr><td>G g</td><td>/g/</td></tr><tr><td>H h</td><td>/h/</td></tr><tr><td>J j</td><td>/ʒ/</td></tr><tr><td>K k</td><td>/k/ لە شێوەی گشتیی نووسین</td></tr><tr><td>L l</td><td>/l/</td></tr><tr><td>M m</td><td>/m/</td></tr><tr><td>N n</td><td>/n/</td></tr><tr><td>P p</td><td>/p/ لە شێوەی گشتیی نووسین</td></tr><tr><td>Q q</td><td>وەستانی بێ‌دەنگی لووتکەیی /q/</td></tr><tr><td>R r / RR rr</td><td>جیاوازیی لە نێوان tap و trill لە هەندێک نووسین و شێوەزاردا</td></tr><tr><td>S s</td><td>/s/</td></tr><tr><td>Ş ş</td><td>/ʃ/</td></tr><tr><td>T t</td><td>/t/ لە شێوەی گشتیی نووسین</td></tr><tr><td>V v</td><td>/v/</td></tr><tr><td>W w</td><td>/w/</td></tr><tr><td>X x</td><td>لە ڕێنووسی ستاندارددا دەنگی /χ/ نیشان دەدات؛ بە پێی شێوەزار دەکرێت جیاوازی هەبێت</td></tr><tr><td>Y y</td><td>/j/</td></tr><tr><td>Z z</td><td>/z/</td></tr></tbody></table>
<p class="klesson-note">ئەم خشتەیە بۆ ناسینی پیت و پەیوەندیی باویانە، نەک تۆماری تەواوی هەموو فونیمەکانی کورمانجی. سەرچاوەی زانکۆی ئەریزۆنا هەندێک جیاوازیی دەنگی و شێوەزاری وەک جیاوازیی aspirated/unaspirated و trill/tap ڕوون دەکاتەوە کە هەمیشە لە ڕێنووسی ستاندارددا نیشان نادرێن.</p></section>
<section class="klesson-card"><h2>٣. پیتە هاوشێوەکان تێکەڵ مەکە</h2><ul><li><strong>C / Ç:</strong> دوو پیتی جیاوازن و بە دوو دەنگی جیاواز نوێنەرایەتی دەکرێن.</li><li><strong>S / Ş:</strong> نیشانەی ç/ş بەشێکە لە پیتەکە؛ لابردنی نیشانەکە ڕێنووس دەگۆڕێت.</li><li><strong>R / RR:</strong> لە هەندێک شێوەی نووسین، دووبارەکردنەوەی r دەتوانێت جیاوازیی trill لە tap نیشان بدات؛ بەڵام ئەم جیاوازییە لە هەموو شێوەزار و نووسینێکدا بە شێوەیەکی یەکسان نانووسرێت.</li><li><strong>X:</strong> لە ڕێنووسی ستانداردی کورمانجی، x پیتی سەربەخۆیە و نابێت بە ks یان پیتێکی دیکە بگۆڕدرێت.</li></ul></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>پیتەکانی C، Ç، S، Ş و X لە ئەلفبێدا دیاری بکە.</li><li>ڕوون بکەرەوە بۆچی پیت و فونیم یەک شت نین.</li><li>بە وشەیەک لە سەرچاوەی فێرکارییەکەوە نموونەی پیتی Ç یان Ş بدۆزەوە و بە ڕێنووسی ڕاست بنووسە.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a>.</li><li>Encyclopaedia Iranica. “Iranian Languages and Scripts: Writing Systems.” <a href="https://www.iranicaonline.org/articles/iran-vi3-writing-systems/" target="_blank" rel="noopener">بەشی سیستەمەکانی نووسین</a>.</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-05.html','kurmanji-course-1','پیتە تایبەتەکان: ç، ş، ê، î، û','<section class="klesson-card"><h2>١. پێنج پیتەکە</h2><p>ئەلفبێی لاتینیی کورمانجی ٣١ پیتی هەیە. پێنج پیت کە بە نیشانەی جیاواز لە نووسینی ئینگلیزی دەردەکەون، بریتین لە <strong>ç، ş، ê، î، û</strong>. ئەم نیشانانە جوانکاری نین؛ بەشێکن لە شێوەی فەرمیی پیتەکە.</p><table class="klesson-table"><thead><tr><th>پیت</th><th>نموونەی کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>ç</td><td>çak</td><td>باش</td><td>لە خشتەی زانکۆی ئەریزۆنا بە /t͡ʃ/ نوێنەرایەتی دەکرێت.</td></tr>
<tr><td>ş</td><td>şaş</td><td>هەڵە</td><td>/ʃ/؛ پیتی ş لە s جیاوازە.</td></tr>
<tr><td>ê</td><td>êş</td><td>ئازار</td><td>ڤاوڵێکی جیاواز لە e.</td></tr>
<tr><td>î</td><td>îro</td><td>ئەمڕۆ</td><td>ڤاوڵێکی جیاواز لە i.</td></tr>
<tr><td>û</td><td>bûz</td><td>سەهۆڵ</td><td>ڤاوڵێکی جیاواز لە u.</td></tr></tbody></table>
<p class="klesson-note">نموونە و واتاکان لە خشتەی ڕێنووس و دەنگناسیی کورمانجیی زانکۆی ئەریزۆنا وەردەگیرێن. دەربڕینی وردی دەنگەکان دەتوانێت بە شێوەزار بگۆڕێت؛ بۆیە ئەم وانەیە بنەمای نووسین دەخاتەڕوو، نەک هەموو جیاوازییە دەنگییەکان.</p></section>
<section class="klesson-card"><h2>٢. نیشانەکە لە نووسین دابمەزرێنە</h2><ul><li><strong>ç</strong> هەمیشە لە نووسین لە <strong>c</strong> جیاوازە؛ لەبیرت نەچێت نیشانەکە لاببەیت.</li><li><strong>ş</strong> لە <strong>s</strong> جیاوازە؛ نووسینی şaş بە شێوەی sash یان sas هەمان ڕێنووس نییە.</li><li><strong>ê</strong> لە <strong>e</strong>، <strong>î</strong> لە <strong>i</strong>، و <strong>û</strong> لە <strong>u</strong> جیاوازن. نیشانەی پیتەکە بە وردی بنووسە.</li><li>لە پیتی گەورەدا شێوەکان بریتین لە <strong>Ç، Ş، Ê، Î، Û</strong>.</li></ul></section>
<section class="klesson-card"><h2>٣. ڕاهێنانی نووسین</h2><ol><li>هەر پیتێک پێنج جار بە شێوەی گەورە و بچووک بنووسە: Ç ç، Ş ş، Ê ê، Î î، Û û.</li><li>ئەم وشانە لە ڕووی پیتە تایبەتەکەوە پۆلێن بکە: çak، şaş، êş، îro، bûz.</li><li>بە بێ گۆڕینی نیشانەکان، هەر وشەیەک لە خشتەکەوە دووبارە بنووسە.</li><li>بە وشەیەکی ڕاستەقینە لە سەرچاوەی فێرکاری، نموونەیەک بۆ ç و ş بدۆزەوە و لەگەڵ وانەکەدا تۆماری بکە.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a> (خشتەی پیت و نموونە وشەکان).</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-06.html','kurmanji-course-1','خوێندنەوە و نووسینی وشەی سادە','<section class="klesson-card"><h2>١. ڕێکاری خوێندنەوە</h2><ol><li>سەرەتا هەموو پیتەکانی وشەکە دیاری بکە؛ بە تایبەتی ç، ş، ê، î و û.</li><li>وشەکە بە پیتەکانی خۆی دابەش بکە، بەڵام لە خوێندنەوەدا وشەکە بە شێوەیەکی سروشتی پێکەوە بخوێنەوە.</li><li>جیاوازیی e/ê، i/î و u/û بپارێزە؛ ئەم جیاوازییانە لە ڕێنووسدا گرنگن.</li><li>واتای وشەکە لە سەرچاوەی باوەڕپێکراو بپشکنە؛ لە تەنیا لەسەر هاوشێوەیی بە کوردیی ناوەندی یان ئینگلیزی بڕیار مەدە.</li></ol></section>
<section class="klesson-card"><h2>٢. وشەی سادە و نموونە</h2><table class="klesson-table"><thead><tr><th>وشە</th><th>واتای کوردی</th><th>تێبینیی ڕێنووسی</th></tr></thead><tbody>
<tr><td>av</td><td>ئاو</td><td>پیتی a و کۆنسۆنەنتی v</td></tr>
<tr><td>dil</td><td>دڵ</td><td>پیتی i جیاوازە لە î</td></tr>
<tr><td>lêv</td><td>لێو</td><td>ê بە نیشانەی خۆی بنووسە</td></tr>
<tr><td>hîn</td><td>هێشتا</td><td>î لە i جیاوازە</td></tr>
<tr><td>qaz</td><td>قاز</td><td>q پیتێکی سەربەخۆیە</td></tr>
<tr><td>qul</td><td>کون</td><td>u لە û جیاوازە</td></tr>
<tr><td>çak</td><td>باش</td><td>ç لە c جیاوازە</td></tr>
<tr><td>şaş</td><td>هەڵە</td><td>ş لە s جیاوازە</td></tr>
<tr><td>roj</td><td>ڕۆژ</td><td>j لە ڕێنووسی کورمانجی پیتی جیاوازە</td></tr>
<tr><td>yek</td><td>یەک</td><td>y دەنگی /j/ نیشان دەدات</td></tr>
</tbody></table><p class="klesson-note">واتاکان بەپێی خشتەی ڕێنووس و نموونەکانی زانکۆی ئەریزۆنا و سەرچاوەی وشەنامەی کورمانجی هاتوون. لە وشەنامەکاندا هەندێک وشە دەتوانێت واتای زیاتر هەبێت؛ لێرەدا تەنیا واتای سەرەکیی پەیوەندیدار بە ڕاهێنانەکە هاتووە.</p></section>
<section class="klesson-card"><h2>٣. ڕاهێنانی نووسین</h2><ol><li>وشەکانی av، dil، lêv، hîn و qaz بە پیتی گەورە و بچووک بنووسە.</li><li>لە وشەکانی çak و şaş نیشانەی تایبەتەکە دیاری بکە و ڕوون بکەرەوە بۆچی نابێت لاببرێت.</li><li>وشەکانی qul و hîn بەراورد بکە و جیاوازیی u و î لە نووسینەکەدا دیاری بکە.</li><li>سێ وشە لە خشتەکە هەڵبژێرە؛ سەرەتا لەسەر کاغەز بنووسە، پاشان بە سەرچاوەکەوە بەراوردیان بکە.</li></ol></section>
<section class="klesson-card"><h2>٤. خۆهەڵسەنگاندن</h2><ul><li>دەتوانم پیتە تایبەتەکان بەبێ لابردنی نیشانەکانیان بنووسم.</li><li>دەتوانم جیاوازیی e/ê، i/î و u/û دیاری بکەم.</li><li>دەتوانم بۆ هەر وشەیەک واتا لە سەرچاوەدا بپشکنم، نەک بە گومان دیاری بکەم.</li></ul></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a>.</li><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English word list</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-07.html','kurmanji-course-1','ڕێنووسی وشە باوەکان','<section class="klesson-card"><h2>١. وشەی ڕۆژانە و شێوەی ڕاستی نووسین</h2><p>لە فێربونی ڕێنووسدا، باشترە وشەکان لە سەرچاوەی فێرکاری یان وشەنامەی کورمانجی بپشکنرێن. ئەم خشتەیە نموونەی وشە و دەربڕینە باوەکان دەخاتەڕوو؛ واتاکان بە کوردیی ناوەندی وەرگێڕدراون بۆ یارمەتیدانی فێرخواز.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>نکته‌ی ڕێنووسی</th></tr></thead><tbody>
<tr><td>Silav</td><td>سڵاو</td><td>پیتی v لە کۆتایی وشەکەدا دێت.</td></tr>
<tr><td>Rojbaş</td><td>ڕۆژ باش / ڕۆژباش</td><td>j و ş بە پیتی جیاواز دەنووسرێن.</td></tr>
<tr><td>Şevbaş</td><td>شەو باش</td><td>ş نابێت بە s بگۆڕدرێت.</td></tr>
<tr><td>Spas</td><td>سوپاس</td><td>شێوەی spas باوە؛ sipasیش وەک شێوەیەکی جیاوازی ناوچەیی دەبینرێت.</td></tr>
<tr><td>Erê</td><td>بەڵێ</td><td>ê پیتی جیاوازە لە e.</td></tr>
<tr><td>Na</td><td>نەخێر</td><td>دوو پیت: n + a.</td></tr>
<tr><td>Bi xêr hatî</td><td>بەخێربێیت</td><td>x و ê لە نووسینەکەدا بپارێزە.</td></tr>
<tr><td>Tu çawa yî?</td><td>تۆ چۆنی؟</td><td>ç و î گرنگن؛ لە پرسیاردا نیشانەی ? بەکاربهێنە.</td></tr>
<tr><td>Ez baş im.</td><td>من باشم.</td><td>ş لە baş پیتێکی جیاوازە.</td></tr>
<tr><td>Ji kerema xwe</td><td>تکایە</td><td>x بە پیتی x دەنووسرێت، نەک ks.</td></tr>
</tbody></table>
<p class="klesson-note">شێوە و واتاکان لە ڕێنمایی دەربڕینە ڕۆژانەکانی Yari و سەرچاوەی ڕێنووسەوە پشکنراون. هەندێک دەربڕین، وەک spas/sipas، دەتوانێت جیاوازیی ناوچەیی یان شێوەی نووسینی هەبێت؛ لە وانەدا شێوەی باو پێشکەش کراوە، نەک ئەوەی شێوەیەکی تر بە هەڵە دابنرێت.</p></section>
<section class="klesson-card"><h2>٢. پێنج هەڵەی ڕێنووسی کە پێویستە لێیان دوور بکەویت</h2><ol><li>لابردنی نیشانە لە ç، ş، ê، î یان û.</li><li>تێکەڵکردنی c و ç یان s و ş.</li><li>گۆڕینی x بۆ ks، بە پێی خوێندنەوەی زمانێکی تر.</li><li>گۆڕینی ڕێنووسی وشە لەسەر بنەمای دەنگی کوردیی ناوەندی، بەبێ پشکنینی وشەنامە.</li><li>گۆڕینی شێوەی ناوچەیی بە شێوەی ستاندارد بەبێ ئەوەی جیاوازییەکە تۆمار بکرێت.</li></ol></section>
<section class="klesson-card"><h2>٣. ڕاهێنانی ڕێنووس</h2><ol><li>دەربڕینەکانی Silav، Rojbaş، Şevbaş و Spas بنووسە و پیتە تایبەتەکان ژمارە بکە.</li><li>لە Tu çawa yî? پیتەکانی ç و î دیاری بکە.</li><li>وشەی Bi xêr hatî دوو جار بنووسە و دڵنیابە لەوەی x و ê لە شوێنی خۆیانن.</li><li>وشەیەکی تر لە وشەنامەی کورمانجی هەڵبژێرە، واتاکەی بپشکنە و هەردووکیان لە تۆماری وانەکەدا بنووسە.</li></ol></section>
<section class="klesson-card"><h2>٤. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/learn/kurdish-greetings/" target="_blank" rel="noopener">Greetings and everyday phrases for beginners (Kurmanji)</a>.</li><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English word list</a>.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a>.</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-08.html','kurmanji-course-1','جیاوازی نێوان نووسین و دەربڕین','<section class="klesson-card"><h2>١. سێ چەمکی جیاواز</h2><ul><li><strong>پیت:</strong> نیشانەیەکی نووسراوە، وەک ç یان ş.</li><li><strong>فونیم:</strong> یەکەیەکی دەنگییە کە دەتوانێت لە زماندا جیاوازیی واتا دروست بکات.</li><li><strong>دەربڕین:</strong> شێوەی ڕاستەقینەی دروستکردنی دەنگەکان لە قسەکردندا؛ دەتوانێت بە پێی شێوەزار، خێرایی و دەوروبەری دەنگی بگۆڕێت.</li></ul><p>ڕێنووس ڕێککەوتنێکی نووسینییە بۆ نوێنەرایەتیی وشەکان. دەربڕین پەیوەندی بە دەنگی قسەکردنەوە هەیە. بۆیە نابێت چاوەڕێ بکەین هەر وردەکارییەکی دەنگی بە پیتێکی جیاواز بنووسرێت.</p></section>
<section class="klesson-card"><h2>٢. نموونە لە کورمانجیدا</h2><table class="klesson-table"><thead><tr><th>نموونە</th><th>چی دەبینین؟</th><th>ڕوونکردنەوە</th></tr></thead><tbody>
<tr><td>e / ê</td><td>دوو پیتی جیاواز</td><td>هەشت ڤاوڵی کورمانجی لە ڕێنووسدا بە هەشت پیت نیشان دەدرێن؛ e و ê جیاوازیی دەنگییان هەیە.</td></tr>
<tr><td>i / î</td><td>دوو پیتی جیاواز</td><td>i و î لە ڕێنووسدا جیاوازن؛ لە نموونەکاندا dil «دڵ» و hîn «هێشتا» هەن.</td></tr>
<tr><td>u / û</td><td>دوو پیتی جیاواز</td><td>u و û جیاوازن؛ qul «کون» و bûz «سەهۆڵ» نموونەن.</td></tr>
<tr><td>r / rr</td><td>جیاوازیی دەنگی هەیە</td><td>لە هەندێک ڕێنووسدا rr بۆ trill و r بۆ tap بەکاردێت؛ بەڵام ئەم جیاوازییە لە نووسینی ستاندارددا هەمیشە بە ڕوونی نیشان نادرێت.</td></tr>
<tr><td>p / pˤ</td><td>جیاوازیی دەنگیی شێوەزاری</td><td>لە هەندێک شێوەزاردا /p/ و /pˤ/ دوو دەنگی جیاوازن؛ /pˤ/ وەستانێکی بێ‌هەناسەیە کە زۆرجار لەگەڵ فەرینجالیزەبوون دێت. ئەم جیاوازییە لە ڕێنووسی لاتینیی ستاندارددا بە پیتی جیاواز نانووسرێت و لە هەموو شێوەزارەکانیشدا بە یەک شێوە نییە.</td></tr>
</tbody></table><p class="klesson-note">جیاوازییەکان لە هەموو ناوچەکاندا بە یەک شێوە نیین. ئەم خشتەیە بنەمای گشتی پیشان دەدات، نەک یاسایەک کە بۆ هەموو شێوەزارەکان بەبێ جیاوازی جێبەجێ بکرێت.</p></section>
<section class="klesson-card"><h2>٣. بۆچی دەربڕین دەتوانێت جیاواز بێت؟</h2><ul><li><strong>جیاوازیی شێوەزاری:</strong> هەندێک دەنگ لە ناوچەیەکدا هەیە و لە ناوچەیەکی تر کەمترە یان جیاواز دەردەکەوێت.</li><li><strong>دەنگە هاوسێیەکان:</strong> دەنگێک دەتوانێت بەهۆی دەنگی پێش یان دوای خۆیەوە کەمێک بگۆڕێت.</li><li><strong>ڕێنووسی ستاندارد:</strong> شێوەی نووسین بۆ خوێندنەوە و پەیوەندیی نووسراو ڕێکخراوە؛ هەموو وردەکارییەکانی دەنگی تۆمار ناکات.</li></ul></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>بە وشەیەکی نموونە ڕوون بکەرەوە کە بۆچی e و ê یەک پیت نین.</li><li>جیاوازیی نێوان پیت، فونیم و دەربڕین بە وشەی خۆت بنووسە.</li><li>لە سەرچاوەکەدا بگەڕێ بۆ نموونەیەک کە جیاوازیی دەنگی لە نووسینی ستاندارددا بە تەواوی نیشان نەدراوە.</li><li>ئەگەر دەربڕینی وشەیەک لە ناوچەیەکی تر جیاوازت بیست، بە خێرایی بە هەڵە ناوی مەبە؛ شێوە و ناوچەکە تۆمار بکە و بە سەرچاوە بەراوردی بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a>.</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li><li>Yari. <a href="https://yari.krd/learn/kurmanji-alphabet/" target="_blank" rel="noopener">The Kurmanji Kurdish alphabet: all 31 letters and how to say them</a>.</li></ol></section>',now()),
('kurmanji-course-1-lesson-09.html','kurmanji-course-1','ناوە کەسییەکان و شوێنەکان','<section class="klesson-card"><h2>١. بنەمای نووسینی ناوی تایبەت</h2><ul><li>ناوی کەس و شوێن لە دەستپێکدا بە پیتی گەورە دەنووسرێن: <em>Azad</em>، <em>Rojîn</em>، <em>Amed</em>.</li><li>پیتە تایبەتەکانی کورمانجی وەک ç، ş، ê، î، û لە ناوەکانیشدا دەپارێزرێن، ئەگەر لە شێوەی هەڵبژێردراوی ناوەکەدا هەبن.</li><li>ناوی کەس بە پێی شێوەی خۆی یان شێوەی فەرمیی خاوەن ناوەکە دەنووسرێت؛ نابێت بەبێ بەڵگە شێوەیەکی تر بۆی دابنرێت.</li><li>هەندێک شوێن ناوی جیاواز لە زمان و شێوەزارە جیاوازەکاندا هەیە. لە دەقی کورمانجی، شێوەی کورمانجیی ناوەکە بەکاربهێنە و لە پێویستدا ناوی باو یان فەرمیی تر لە کەوانەدا زیاد بکە.</li></ul></section>
<section class="klesson-card"><h2>٢. نموونەی ناوە کەسییەکان</h2><table class="klesson-table"><thead><tr><th>ناو</th><th>تێبینیی ڕێنووسی</th></tr></thead><tbody><tr><td>Azad</td><td>دەستپێک بە پیتی گەورەی A.</td></tr><tr><td>Rojîn</td><td>پیتی î بە هەمان شێوەی ڕێنووسی ناوەکە دەپارێزرێت.</td></tr><tr><td>Şilan</td><td>پیتی ş دەبێت لە نووسینەوەدا نەگۆڕدرێت بۆ s.</td></tr><tr><td>Berfîn</td><td>پیتی ê/î بە پێی شێوەی ناوەکە ورد دەنووسرێت.</td></tr><tr><td>Mem û Zîn</td><td>لە ناوی ئەدەبیی ناسراودا، نووسینی ناو و پەیوەندییەکەی دەپارێزرێت.</td></tr></tbody></table><p class="klesson-note">ئەم ناوانە نموونەی ڕاهێنانن؛ مەبەست فێربوونی ڕێنووسە، نەک بانگەشەی ئەوەی کە تەنها ئەم ناوانە لە ناوچەکەدا بەکاردێن.</p></section>
<section class="klesson-card"><h2>٣. نموونەی ناوی شوێن</h2><table class="klesson-table"><thead><tr><th>شێوەی ناو</th><th>ناوی ناسراوی هاوتا</th><th>تێبینی</th></tr></thead><tbody><tr><td>Amed</td><td>Diyarbakır</td><td>هەردوو شێوەکە لە بەکارهێنانی جیاوازدا دەبینرێن.</td></tr><tr><td>Hewlêr</td><td>Erbil</td><td>شێوەی ناوەکە لە زمان و کۆنتێکستدا دەگۆڕێت.</td></tr><tr><td>Wan</td><td>Van</td><td>جیاوازیی نووسین لە سیستەمی لاتینیی کورمانجی و شێوەی تورکیی ناوەکەدا دەبینرێت.</td></tr><tr><td>Qamişlo</td><td>—</td><td>پیتی ş بە ڕوونی دەپارێزرێت.</td></tr></tbody></table><p>لە کاتێکدا شوێنێک چەند ناوی هەیە، بە پێی مەبەستی دەقەکە ناوی گونجاو هەڵبژێرە. لە دەقی ئەکادیمیکدا، لە یەکەم جاردا دەتوانرێت ناوی بەکارهاتوو و شێوەی هاوتاکەی پێکەوە بنووسرێن.</p></section>
<section class="klesson-card"><h2>٤. ڕێنووسی ناو لە ڕستەدا</h2><p><strong>Ez li Amedê dijîm.</strong> — من لە ئەمید دەژیم.</p><p><strong>Ez ji Qamişloyê me.</strong> — من خەڵکی قامشلۆم.</p><p><strong>Navê min Azad e.</strong> — ناوی من ئازادە.</p><p class="klesson-note">لە کورمانجیدا، ناوی شوێن لە هەندێک پێکهاتەدا دەتوانێت شێوەی ڕێزمانیی وەربگرێت؛ بۆ نموونە لەگەڵ <em>li</em> «لە» و <em>ji</em> «لە/خەڵکی». ئەم گۆڕانانە تەنها ڕێنووسی ناو نین، بەڵکو بەشێکن لە ڕێزمان و لە وانەکانی دواتردا بە فراوانی دەخوێندرێنەوە.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>ئەم ناوانە بە پیتی گەورە و پیتە تایبەتەکانیان بنووسە: rojîn، şilan، qamişlo.</li><li>سێ ناوی کەسی و دوو ناوی شوێن بنووسە؛ شێوەی نووسینەکەیان لە سەرچاوەیەکی باوەڕپێکراو بپشکنە.</li><li>ڕستەی <em>Navê min Azad e.</em> وەرگێڕە و ناوی کەسییەکە دیاری بکە.</li><li>بۆ شوێنێک کە دوو ناوی باوی هەیە، نموونەیەک بنووسە و ڕوون بکەرەوە بۆچی پێویستە کۆنتێکست دیاری بکرێت.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Kurdi School. <a href="https://kurdischool.com/grammar.html" target="_blank" rel="noopener">Kurmanji grammar</a> — نموونەی ناوی شوێن و بەکارهێنانی <em>li</em> و <em>ji</em>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">خوێندنەوەی کتێب</a>.</li><li>Navên Kurdî. <a href="https://www.kurdishnames.org/en/sources/" target="_blank" rel="noopener">سەرچاوەکان بۆ ناوە کوردییەکان</a> — بۆ پشکنینی ڕەچەڵەک و شێوەی ناوەکان، نەک وەک یاسایەکی یەکسان بۆ هەموو ناوچەکان.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-10.html','kurmanji-course-1','دەربڕینە سەرەتاییەکان','<section class="klesson-card"><h2>١. سڵاو و ماڵئاوایی</h2><table class="klesson-table"><thead><tr><th>دەربڕینی کورمانجی</th><th>واتا بە کوردی</th><th>کات و بەکارهێنان</th></tr></thead><tbody>
<tr><td>Silav!</td><td>سڵاو!</td><td>سڵاوکردنی گشتی.</td></tr>
<tr><td>Rojbaş!</td><td>بەیانیت باش / ڕۆژباش!</td><td>سڵاوێکی باو لە کاتی ڕۆژدا.</td></tr>
<tr><td>Şevbaş!</td><td>شەوت باش!</td><td>بۆ ماڵئاوایی، زۆرجار لە ئێوارە یان شەودا.</td></tr>
<tr><td>Bi xatirê te!</td><td>خواحافیز / ماڵئاوایی!</td><td>ماڵئاوایی؛ بەکارهێنان دەتوانێت بە کۆنتێکست بگۆڕێت.</td></tr>
<tr><td>Bi xêr hatî!</td><td>بەخێر بێیت!</td><td>بەخێرهاتن بۆ تاک؛ شێوەکە بەپێی ژمارە و ڕەگەز دەتوانێت بگۆڕێت.</td></tr>
</tbody></table><p class="klesson-note">دەربڕینەکان لە شێوەزار و بارودۆخی کۆمەڵایەتیی جیاوازدا هەندێک جیاوازییان هەیە. لە گفتوگۆی فەرمی و نافەرمی‌دا، کۆنتێکست و شێوەی بەکارهێنان لەبەرچاو بگرە.</p></section>
<section class="klesson-card"><h2>٢. ناساندن و پرسیارکردن لە بارودۆخ</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>Tu çawa yî?</td><td>چۆنی؟ (بۆ تاک)</td></tr>
<tr><td>Ez baş im.</td><td>من باشم.</td></tr>
<tr><td>Navê min Azad e.</td><td>ناوی من ئازادە.</td></tr>
<tr><td>Tu kî yî?</td><td>تۆ کێیت؟</td></tr>
<tr><td>Ez ji ... me.</td><td>من خەڵکی ...م / لە ...م.</td></tr>
</tbody></table><p>لە نموونەی <em>Ez ji ... me</em> شوێنەکە بە ناوی گونجاو پڕ بکەرەوە. لە ڕستەی <em>Tu çawa yî?</em>، جێناوی <em>tu</em> بۆ تاکە؛ شێوەی بانگکردنی کۆ لە وانەکانی دواتردا دەخوێندرێتەوە.</p></section>
<section class="klesson-card"><h2>٣. سوپاس و داواکردنی یارمەتی</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>Spas!</td><td>سوپاس!</td><td>دەربڕینی سوپاسگوزاری.</td></tr>
<tr><td>Ji kerema xwe.</td><td>تکایە.</td><td>داواکردنی ڕێزدارانە.</td></tr>
<tr><td>Erê.</td><td>بەڵێ.</td><td>وەڵامی ئەرێنی.</td></tr>
<tr><td>Na.</td><td>نەخێر.</td><td>وەڵامی نەرێنی.</td></tr>
<tr><td>Biborîne.</td><td>ببورە.</td><td>داوای لێبوردن؛ شێوە و ڕێنووس دەتوانێت لە سەرچاوەکاندا جیاواز بێت.</td></tr>
</tbody></table></section>
<section class="klesson-card"><h2>٤. گفتوگۆی کورت</h2><p><strong>A:</strong> Silav! Tu çawa yî?</p><p><strong>B:</strong> Silav! Ez baş im, spas. Tu çawa yî?</p><p><strong>A:</strong> Ez jî baş im.</p><p class="klesson-note">واتا: A سڵاو دەکات و دەپرسێت چۆنە. B وەڵام دەدات و سوپاس دەکات، پاشان پرسیارەکە دەگەڕێنێتەوە. وشەی <em>jî</em> لێرەدا واتای «هەروەها/هەروەها من» دەگەیەنێت.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>بە کورمانجی سڵاو بکە و بپرسە کەسەکە چۆنە.</li><li>بە ڕستەیەکی سادە خۆت بناسێنە: <em>Navê min ... e.</em></li><li>بۆ «سوپاس»، «تکایە» و «بەڵێ» هاوتای کورمانجی بنووسە.</li><li>گفتوگۆی دوو کەسییەک دروست بکە کە تێیدا سڵاو، پرسیار لە بارودۆخ و سوپاس هەبێت.</li><li>دەربڕینێک هەڵبژێرە و لە دوو سەرچاوەدا شێوەی نووسین و واتاکەی بەراورد بکە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/learn/kurdish-greetings/" target="_blank" rel="noopener">Kurdish greetings and everyday phrases</a>.</li><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English dictionary</a>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-11.html','kurmanji-course-1','جێناوە کەسییەکان','<section class="klesson-card"><h2>١. جێناوە ڕاستەوخۆکان</h2><p>ئەم جێناوانە لە ڕستەی ئاساییی ئێستادا زۆرجار وەک بکەر دێن.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>کەس و ژمارە</th></tr></thead><tbody>
<tr><td>ez</td><td>من</td><td>کەسی یەکەم، تاک</td></tr>
<tr><td>tu</td><td>تۆ</td><td>کەسی دووەم، تاک</td></tr>
<tr><td>ew</td><td>ئەو</td><td>کەسی سێیەم، تاک</td></tr>
<tr><td>em</td><td>ئێمە</td><td>کەسی یەکەم، کۆ</td></tr>
<tr><td>hûn</td><td>ئێوە / ئێوەی بەڕێز</td><td>کەسی دووەم، کۆ؛ لە هەندێک کۆنتێکستدا بۆ ڕێزگرتنیش.</td></tr>
<tr><td>ew</td><td>ئەوان</td><td>کەسی سێیەم، کۆ</td></tr>
</tbody></table><p class="klesson-note">جێناوی <em>ew</em> بەپێی کۆنتێکست دەتوانێت واتای «ئەو» یان «ئەوان» بدات. لە نووسین و گفتوگۆدا، کردار و دەوروبەری ڕستە یارمەتی دەدەن ژمارەکە بناسرێت.</p></section>
<section class="klesson-card"><h2>٢. نموونە لە ڕستەی سادەدا</h2><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th><th>جێناو</th></tr></thead><tbody>
<tr><td>Ez xwendekar im.</td><td>من خوێندکارم.</td><td>ez</td></tr>
<tr><td>Tu baş î.</td><td>تۆ باشیت.</td><td>tu</td></tr>
<tr><td>Ew mamoste ye.</td><td>ئەو مامۆستایە.</td><td>ew</td></tr>
<tr><td>Em li vir in.</td><td>ئێمە لێرەین.</td><td>em</td></tr>
<tr><td>Hûn baş in.</td><td>ئێوە باشن.</td><td>hûn</td></tr>
<tr><td>Ew hevalên min in.</td><td>ئەوان هاوڕێکانی منن.</td><td>ew</td></tr>
</tbody></table><p>لە ڕستەکانی ناساندندا، پاش جێناو شێوەی گونجاوی پەیوەندیی «بوون» دێت؛ وەک <em>im</em>، <em>î</em>، <em>ye</em> و <em>in</em>. ئەم شێوانە بە پێی کۆتاییی ناو یان هاوەڵناو و ڕێکخستنی ڕستە دەتوانن جیاواز بن.</p></section>
<section class="klesson-card"><h2>٣. جێناوە ناڕاستەوخۆکان</h2><p>کورمانجی جگە لە شێوەی ڕاستەوخۆ، کۆمەڵێک شێوەی ناڕاستەوخۆی جێناوی هەیە. ئەم شێوانە لە خاوەنداریدا، دوای پێشگرەکان و لە هەندێک ڕستەی کرداریدا بەکاردێن. بەکارهێنانیان تەنها بە یاسای «ڕابردوو» کورت ناکرێتەوە.</p><table class="klesson-table"><thead><tr><th>ڕاستەوخۆ</th><th>ناڕاستەوخۆ</th><th>واتای بنەڕەتی</th></tr></thead><tbody>
<tr><td>ez</td><td>min</td><td>من / ـی من</td></tr>
<tr><td>tu</td><td>te</td><td>تۆ / ـی تۆ</td></tr>
<tr><td>ew</td><td>wî (نێر) / wê (مێ)</td><td>ئەو / ـی ئەو</td></tr>
<tr><td>em</td><td>me</td><td>ئێمە / ـی ئێمە</td></tr>
<tr><td>hûn</td><td>we</td><td>ئێوە / ـی ئێوە</td></tr>
<tr><td>ew</td><td>wan</td><td>ئەوان / ـی ئەوان</td></tr>
</tbody></table><p><strong>نموونە:</strong> <em>navê min</em> = ناوی من؛ <em>bi te re</em> = لەگەڵ تۆ. لەم دوو نموونەدا <em>min</em> و <em>te</em> شێوەی ناڕاستەوخۆن.</p><p class="klesson-note">جیاوازیی ڕاستەوخۆ و ناڕاستەوخۆ لە کورمانجیدا بابەتێکی گرنگی ڕێزمانە. بەکارهێنانی شێوەکان بە پێی پێکهاتەی ڕستە و کردار دەگۆڕێت؛ وردەکارییەکانی دواتر لە وانەکانی ڕێزماندا دەخوێندرێنەوە.</p></section>
<section class="klesson-card"><h2>٤. جێناوی ڕەنگدانەوەیی</h2><p><em>xwe</em> جێناوێکی ڕەنگدانەوەییە کە لە چەند کۆنتێکستێکدا بەکاردێت بۆ ئەوەی بگەڕێتەوە بۆ بکەری ڕستە.</p><p><strong>Ez ji dayika xwe hez dikim.</strong> — من خۆشم لە دایکی خۆم دەوێت.</p><p>لە نموونەکەدا <em>xwe</em> پەیوەندی بە بکەری <em>Ez</em> ـەوە هەیە. وردەکاریی بەکارهێنانی <em>xwe</em> و جێناوەکانی تر لە وانەیەکی تایبەتدا زیاتر دەکرێتەوە.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>واتای ئەم جێناوانە بنووسە: <em>ez, tu, ew, em, hûn, ew</em>.</li><li>لە ڕستەی <em>Em li vir in.</em> جێناوی کەسی دیاری بکە و واتای ڕستەکە بنووسە.</li><li>جێناوی ڕاستەوخۆ و ناڕاستەوخۆی <em>ez</em>، <em>tu</em> و <em>em</em> لە خشتەیەکدا جیا بکەرەوە.</li><li>واتای <em>navê min</em> و <em>bi te re</em> بنووسە و جێناوی ناڕاستەوخۆ دیاری بکە.</li><li>بە جێناوی <em>xwe</em> ڕستەیەکی سادە بنووسە و ڕوون بکەرەوە بۆ چی بەکارت هێناوە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Syntax and Pronouns</a>.</li><li>Haig, Geoffrey & Öpengin, Ergin (2018). “Northern Kurdish (Kurmanjî).” <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>. <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-12.html','kurmanji-course-1','جێناوە ئاماژەییەکان','<section class="klesson-card"><h2>١. ئاماژەکردن بە نزیک و دوور</h2><p>لە کورمانجیدا شێوەی ئاماژەیی بە پێی نزیکی و دووری و پێکهاتەی ڕستە دەگۆڕێت. لە فێربوونی سەرەتاییدا ئەم دوو جیاوازییە گرنگن:</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتای نزیک</th><th>واتای دوور</th></tr></thead><tbody>
<tr><td>ev</td><td>ئەمە / ئەم</td><td>—</td></tr>
<tr><td>ew</td><td>—</td><td>ئەوە / ئەو</td></tr>
</tbody></table><p class="klesson-note">شێوەی <em>ew</em> هەروەها جێناوی کەسیی سێیەمیشە (ئەو/ئەوان). واتاکەی لە کۆنتێکست و پێکهاتەی ڕستەوە دەردەکەوێت؛ بۆیە نابێت هەموو جارێک بە یەک شێوە وەربگێڕدرێت.</p></section>
<section class="klesson-card"><h2>٢. جێناوی ئاماژەیی یان دیارخەری ئاماژەیی؟</h2><ul><li><strong>بەکارهێنانی سەربەخۆ:</strong> وشەکە بە تەنیا وەک جێناو دێت، بۆ نموونە <em>Ev baş e.</em> — ئەمە باشە.</li><li><strong>لەگەڵ ناو:</strong> وشەی ئاماژەیی لەگەڵ ناو دێت و ناوەکە دیاری دەکات، وەک <em>ev pirtûk</em> — ئەم کتێبە (نموونەی فێرکاری).</li></ul><p>لە ڕێزماندا، بەپێی ئەوەی وشەکە بە تەنیا شوێنی ناو دەگرێتەوە یان ناوێک دیاری دەکات، دەتوانرێت بە جێناوی ئاماژەیی یان دیارخەری ئاماژەیی ناوببرێت.</p></section>
<section class="klesson-card"><h2>٣. نموونە لە ڕستەدا</h2><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th><th>ئەرکی وشەی ئاماژەیی</th></tr></thead><tbody>
<tr><td>Ev baş e.</td><td>ئەمە باشە.</td><td>سەربەخۆ؛ جێناوی ئاماژەیی.</td></tr>
<tr><td>Ew baş e.</td><td>ئەوە باشە / ئەو باشە.</td><td>واتاکە بە کۆنتێکست دیاری دەکرێت.</td></tr>
<tr><td>Ev pirtûk baş e.</td><td>ئەم کتێبە باشە.</td><td>لەگەڵ ناو هاتووە؛ دیارخەر.</td></tr>
<tr><td>Ew mal mezin e.</td><td>ئەو ماڵە گەورەیە.</td><td>لەگەڵ ناو هاتووە؛ دیارخەر.</td></tr>
</tbody></table><p class="klesson-note">ئەم ڕستانە نموونەی فێرکاریین بۆ جیاکردنەوەی ئەرکەکان. شێوەی پەیوەندیی ناو و دیارخەر و ڕێکخستنی ڕستە لە سەرچاوە و شێوەزارەکاندا دەتوانێت جیاوازی هەبێت؛ بۆ بەکارهێنانی زانستی، نموونەکان لە ڕێزمانێکی کورمانجیی دیاریکراودا بپشکنە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>واتای <em>ev</em> و <em>ew</em> بنووسە و بۆ هەر یەک نموونەیەک دروست بکە.</li><li>لە ڕستەی <em>Ev baş e.</em> وشەی ئاماژەیی دیاری بکە و بڵێ بە تەنیا هاتووە یان لەگەڵ ناو.</li><li>جیاوازیی نێوان «ئەمە باشە» و «ئەم کتێبە باشە» بە کورمانجی بنووسە.</li><li>دوو شت لە دەوروبەرت دیاری بکە؛ یەکێکیان نزیک و یەکێکیان دوورە. بە شێوەیەکی سادە بە <em>ev</em> و <em>ew</em> ئاماژەیان پێ بکە.</li><li>لە سەرچاوەیەکی ڕێزمانی، نموونەیەکی تر بدۆزەوە و لەگەڵ ئەم نموونانە بەراوردی بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Thackston, W. M. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Haig, Geoffrey & Öpengin, Ergin (2018). “Northern Kurdish (Kurmanjî).” <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>. <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — grammar and language resources</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-13.html','kurmanji-course-1','ژمارەکان ١–٢٠','<section class="klesson-card"><h2>١. ژمارەکان لە ١ تا ٢٠</h2><table class="klesson-table"><thead><tr><th>ژمارە</th><th>کورمانجی (لاتینی)</th><th>واتا</th></tr></thead><tbody>
<tr><td>1</td><td>yek</td><td>یەک</td></tr><tr><td>2</td><td>du</td><td>دوو</td></tr><tr><td>3</td><td>sê</td><td>سێ</td></tr><tr><td>4</td><td>çar</td><td>چوار</td></tr><tr><td>5</td><td>pênc</td><td>پێنج</td></tr><tr><td>6</td><td>şeş</td><td>شەش</td></tr><tr><td>7</td><td>heft</td><td>حەوت</td></tr><tr><td>8</td><td>heşt</td><td>هەشت</td></tr><tr><td>9</td><td>neh</td><td>نۆ</td></tr><tr><td>10</td><td>deh</td><td>دە</td></tr><tr><td>11</td><td>yanzdeh</td><td>یازدە</td></tr><tr><td>12</td><td>diwanzdeh</td><td>دوازدە</td></tr><tr><td>13</td><td>sêzdeh</td><td>سێزدە</td></tr><tr><td>14</td><td>çardeh</td><td>چواردە</td></tr><tr><td>15</td><td>panzdeh</td><td>پازدە</td></tr><tr><td>16</td><td>şanzdeh</td><td>شازدە</td></tr><tr><td>17</td><td>hevdeh</td><td>حەڤدە</td></tr><tr><td>18</td><td>hejdeh</td><td>هەژدە</td></tr><tr><td>19</td><td>nozdeh</td><td>نۆزدە</td></tr><tr><td>20</td><td>bîst</td><td>بیست</td></tr>
</tbody></table><p class="klesson-note">لە سەرچاوەکاندا بۆ هەندێک ژمارە چەند شێوەی نووسین هەیە؛ بۆ نموونە ١١، ١٢ و ١٥. لەم وانەیەدا یەک شێوە بۆ فێربوون هەڵبژێردراوە، بەڵام لە دەقی ئەکادیمیکدا شێوەی بەکارهاتوو لە سەرچاوەی دیاریکراو پێویستە بە یەکسانی بپارێزرێت.</p></section>
<section class="klesson-card"><h2>٢. تێبینیی ڕێنووسی</h2><ul><li>پیتە نیشان‌دارەکان وەک <em>ê</em>، <em>ş</em> و <em>ç</em> بە وردی بنووسە؛ پیتەکان بەبێ نیشانە جێگۆڕکێیان پێ مەکە.</li><li>ژمارەی ٣ بە <em>sê</em> نووسراوە، نەک <em>se</em>.</li><li>ژمارەی ٨ بە <em>heşt</em> نووسراوە، و ژمارەی ٢٠ بە <em>bîst</em>.</li><li>هەندێک سەرچاوە لە شێوەی ژمارەکانی ١١–١٦دا جیاوازن؛ هەمان شێوەی سەرچاوەکەت بۆ تەواوی وانە یەکسان بەکاربهێنە.</li></ul></section>
<section class="klesson-card"><h2>٣. ژمارە لە ڕستەدا</h2><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th></tr></thead><tbody><tr><td>Ez du pirtûkan dixwînim.</td><td>من دوو کتێب دەخوێنمەوە.</td></tr><tr><td>Min sê pênûs hene.</td><td>من سێ پێنووسم هەیە.</td></tr><tr><td>Ew pênc rojan li vir e.</td><td>ئەو بۆ ماوەی پێنج ڕۆژ لێرەیە.</td></tr></tbody></table><p class="klesson-note">ئەم ڕستانە نموونەی فێرکاریین. لە <em>Ez du pirtûkan dixwînim</em>دا، <em>pirtûkan</em> فۆڕمی کۆی ناڕاستەوخۆی <em>pirtûk</em>ە، چونکە بەرکاری کردارێکی ئێستایە؛ هەروەها دەربڕینی ماوەی کات، وەک <em>pênc rojan</em>، لە کورمانجیدا فۆڕمی ناڕاستەوخۆ وەردەگرێت. لە ڕستەکانی دیکەشدا ڕێکخستنی ناو و کردار و شێوەی خاوەنداری بە پێی پێکهاتەی ڕستە دەگۆڕێت. ئەگەر لە سەرچاوەی وانەیەکدا شێوەیەکی تر هەیە، لەو وانەیەدا شێوەی سەرچاوەکە بپارێزە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ژمارەکانی ١ تا ١٠ بە کورمانجی بنووسە.</li><li>واتای <em>yanzdeh</em>، <em>şanzdeh</em> و <em>bîst</em> بنووسە.</li><li>ئەم ژمارانە بە وشە بنووسە: ٤، ٨، ١٢، ١٧، ٢٠.</li><li>سێ شتی ناو ژوورەکەت هەڵبژێرە و ژمارەیان بە کورمانجی بنووسە.</li><li>ژمارەکانی ١١–١٦ لە دوو سەرچاوەدا بەراورد بکە و جیاوازیی نووسینیان تۆمار بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Omniglot. <a href="https://www.omniglot.com/language/numbers/kurdish.htm" target="_blank" rel="noopener">Northern (Kurmanji) Kurdish numbers</a>.</li><li>KurdiPedia, <em>Kurmanji Kurdish, Lesson 2</em> — بەشی Hejmar / Numbers. <a href="https://www.kurdipedia.org/files/books/2023/474430.PDF" target="_blank" rel="noopener">PDF</a>.</li><li>CrowdsourceKurdish. <a href="https://github.com/CrowdsourceKurdish/Kurdish-Numbers-to-Words" target="_blank" rel="noopener">Kurdish (Kurmanji) Numbering Rules</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-14.html','kurmanji-course-1','ڕەنگ و ناوی شتە ڕۆژانەکان','<section class="klesson-card"><h2>١. ناوی ڕەنگەکان</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>sor</td><td>سوور</td><td>ڕەنگی سوور.</td></tr>
<tr><td>şîn</td><td>شین</td><td>پیتی ş و î بە وردی بنووسە.</td></tr>
<tr><td>kesk</td><td>سەوز</td><td>لە سەرچاوە و ناوچەکاندا واتای ڕەنگەکە بپشکنە.</td></tr>
<tr><td>zer</td><td>زەرد</td><td>ڕەنگی زەرد.</td></tr>
<tr><td>reş</td><td>ڕەش</td><td>پیتی ş لە کۆتاییدا دەپارێزرێت.</td></tr>
<tr><td>spî</td><td>سپێ</td><td>پیتی î لە کۆتاییدا دەپارێزرێت.</td></tr>
<tr><td>qehweyî</td><td>قاوەیی</td><td>شێوەی وشەکە لە سەرچاوەکاندا دەتوانێت جیاواز بێت.</td></tr>
</tbody></table><p class="klesson-note">لە کورمانجیدا ڕەنگەکان وەک هاوەڵناو بەکاردێن؛ شێوەی ڕستە و ڕێکخستنی وشەکان بە پێی پێکهاتەی ڕێزمانی دەگۆڕێت. لەم وانەیەدا وشەکان بۆ ناسین و ڕاهێنانی سەرەتایی پێشکەش کراون.</p></section>
<section class="klesson-card"><h2>٢. ناوی شتە ڕۆژانەکان</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>جۆری شت</th></tr></thead><tbody>
<tr><td>pirtûk</td><td>کتێب</td><td>خوێندن</td></tr>
<tr><td>pênûs</td><td>پێنووس</td><td>نووسین</td></tr>
<tr><td>defter</td><td>دەفتەر</td><td>خوێندن و نووسین</td></tr>
<tr><td>derî</td><td>دەرگا</td><td>ماڵ و بینا</td></tr>
<tr><td>kursî</td><td>کورسی</td><td>کەرەستەی ماڵ</td></tr>
<tr><td>mase</td><td>مێز</td><td>کەرەستەی ماڵ</td></tr>
<tr><td>telefon</td><td>تەلەفۆن</td><td>پەیوەندی</td></tr>
<tr><td>av</td><td>ئاو</td><td>خواردنەوە</td></tr>
<tr><td>nan</td><td>نان</td><td>خواردن</td></tr>
<tr><td>mal</td><td>ماڵ</td><td>شوێن</td></tr>
</tbody></table><p class="klesson-note">وشەی ناوچەیی یان وەرگیراو دەتوانێت لە شێوەزارەکاندا جیاواز بێت. لە نووسینی ئەکادیمیکدا، ئەگەر شێوەیەکی دیاریکراو لە سەرچاوەیەکەوە وەردەگریت، هەمان شێوە بە یەکسانی بەکاربهێنە.</p></section>
<section class="klesson-card"><h2>٣. ڕستەی سادە</h2><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>Ev pirtûk sor e.</td><td>ئەم کتێبە سوورە.</td></tr>
<tr><td>Ev pênûs reş e.</td><td>ئەم پێنووسە ڕەشە.</td></tr>
<tr><td>Av sar e.</td><td>ئاوەکە ساردە.</td></tr>
<tr><td>Telefon li ser maseyê ye.</td><td>تەلەفۆنەکە لەسەر مێزەکەیە.</td></tr>
<tr><td>Ez pirtûkê dixwînim.</td><td>من کتێبەکە دەخوێنمەوە.</td></tr>
</tbody></table><p class="klesson-note">لە نموونەکاندا وشەی ئاماژەیی و هەندێک پاشگری ڕێزمانی هەن. ئەم ڕستانە بۆ ڕاهێنانی سەرەتایین؛ بۆ بەکارهێنانی فەرمی، شێوەی ڕستە لەگەڵ ڕێزمانی سەرچاوەکەت بپشکنە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ناوی شەش ڕەنگ بە کورمانجی بنووسە و واتاکانیان زیاد بکە.</li><li>ناوی پێنج شتی دەوروبەرت بنووسە؛ هەوڵ بدە شێوەی لاتینی و پیتە تایبەتەکان ڕاست بن.</li><li>بە وشەیەک لە خشتەی ڕەنگەکان ڕستەیەک دروست بکە.</li><li>ڕستەیەک بنووسە کە شتێک و شوێنی ئەو شتە دیاری بکات.</li><li>دوو وشە لە سەرچاوەیەکی دیکەدا بپشکنە و ئەگەر شێوەی جیاوازت بینی، جیاوازییەکە تۆمار بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English dictionary</a>.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — language resources</a>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-15.html','kurmanji-course-1','وشەکانی خێزان','<section class="klesson-card"><h2>١. وشە سەرەتاییەکانی خێزان</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>malbat</td><td>خێزان</td><td>بۆ کۆی ئەندامانی خێزان بەکاردێت.</td></tr>
<tr><td>dayik</td><td>دایک</td><td>وشەی بنەڕەتی.</td></tr>
<tr><td>bav</td><td>باوک</td><td>وشەی بنەڕەتی.</td></tr>
<tr><td>kur</td><td>کوڕ</td><td>واتا بە پێی ڕستە دەتوانێت بۆ کوڕ/منداڵی نێر بێت.</td></tr>
<tr><td>keç</td><td>کچ</td><td>پیتی ç لە کۆتاییدا دەپارێزرێت.</td></tr>
<tr><td>bira</td><td>برا</td><td>پەیوەندیی برا.</td></tr>
<tr><td>xwişk</td><td>خوشک</td><td>پیتی ş لە نووسینەکەدا گرنگە.</td></tr>
<tr><td>kal</td><td>باپیر</td><td>وشەکە لە هەندێک بەکارهێناندا واتای تەمەن‌دار/پیر هەیە؛ واتای ورد لە سەرچاوە بپشکنە.</td></tr>
<tr><td>pîrik</td><td>داپیر</td><td>بەکارهێنان و شێوەی ناوچەیی دەتوانێت جیاواز بێت.</td></tr>
<tr><td>mêr</td><td>مێرد / پیاو</td><td>واتاکە لە ڕستەدا دیاری دەبێت.</td></tr>
<tr><td>jin</td><td>ژن</td><td>واتاکە بە پێی بەکارهێنان ڕوون دەبێتەوە.</td></tr>
<tr><td>zarok</td><td>منداڵ</td><td>وشەی گشتی بۆ منداڵ.</td></tr>
</tbody></table><p class="klesson-note">وشەکانی خێزان لە شێوەزار و سەرچاوە جیاوازەکاندا دەکرێت شێوەی جیاوازیان هەبێت. بۆ ناونانی وردی پەیوەندییەکانی خێزان، واتای وشەکە لە ڕستە و سەرچاوەی دیاریکراودا بپشکنە.</p></section>
<section class="klesson-card"><h2>٢. خاوەنداری و پەیوەندیی خێزانی</h2><p>بۆ باسکردنی ئەندامانی خێزان، لە کورمانجیدا خاوەنداری دەتوانێت بە جێناو و پاشگر یان پێکهاتەی ڕێزمانی دیاریکراو دەرببڕدرێت. لەم ئاستەدا، پێش ئەوەی شێوەیەکی درێژتر فێرببیت، ناوی بنەڕەتیی وشەکان بناسە.</p><table class="klesson-table"><thead><tr><th>دەربڕین</th><th>واتا</th></tr></thead><tbody><tr><td>dayika min</td><td>دایکی من</td></tr><tr><td>bavê min</td><td>باوکی من</td></tr><tr><td>birayê min</td><td>برای من</td></tr><tr><td>xwişka min</td><td>خوشکی من</td></tr></tbody></table><p class="klesson-note">ئەم دەربڕینانە بۆ ناساندنی پێکهاتەی وشەکانن؛ شێوەی پاشگر و ڕێکخستنی ناو دەتوانێت بە پێی حاڵەتی ڕێزمانی و شێوەی ڕستە بگۆڕێت. لە ڕستەی تەواودا بە سەرچاوەی ڕێزمانی پشکنینیان بکە.</p></section>
<section class="klesson-card"><h2>٣. ڕستەی سادە</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody><tr><td>Ev dayika min e.</td><td>ئەمە دایکی منە.</td></tr><tr><td>Navê bavê min Azad e.</td><td>ناوی باوکم ئازادە.</td></tr><tr><td>Ez bi malbata xwe re dijîm.</td><td>من لەگەڵ خێزانەکەم دەژیم.</td></tr></tbody></table><p class="klesson-note">ڕستەکان بۆ ڕاهێنانی سەرەتایین. بۆ فێربوونی ڕێزمانی خاوەنداری و حاڵەتەکان، وانەکانی دواتر و سەرچاوەی ڕێزمانی بەکاربهێنە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>وشەکانی دایک، باوک، برا، خوشک و منداڵ بە کورمانجی بنووسە.</li><li>وشەی <em>malbat</em> لە ڕستەیەکی سادەدا بەکاربهێنە.</li><li>دەربڕینێک بۆ «دایکی من» و «براکەم» بنووسە و لە سەرچاوەیەکی ڕێزمانیدا پشکنینیان بکە.</li><li>بە سێ ڕستە خێزانەکەت بناسێنە؛ ئەگەر ناتەوێت زانیاریی کەسی بەکاربهێنیت، خێزانێکی خەیاڵی هەڵبژێرە.</li><li>جیاوازیی وشەی «کوڕ» و «منداڵ» لە ڕستەی خۆتدا ڕوون بکەوە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English dictionary</a>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish resources</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-16.html','kurmanji-course-1','ڕۆژەکانی هەفتە و کات','<section class="klesson-card"><h2>١. ڕۆژەکانی هەفتە</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>duşem</td><td>دووشەممە</td></tr><tr><td>sêşem</td><td>سێشەممە</td></tr><tr><td>çarşem</td><td>چوارشەممە</td></tr><tr><td>pêncşem</td><td>پێنجشەممە</td></tr><tr><td>în</td><td>هەینی</td></tr><tr><td>şemî</td><td>شەممە</td></tr><tr><td>yekşem</td><td>یەکشەممە</td></tr></tbody></table><p class="klesson-note">ناونانی ڕۆژەکان لە سەرچاوە و ناوچە جیاوازەکاندا دەتوانێت شێوەی جیاواز هەبێت. لەم وانەیەدا شێوەیەکی باوی نووسینی کورمانجی بەکار هاتووە؛ بۆ فێربوونی ڕێنووسی ناوچەیەکی دیاریکراو، فەرهەنگەکە بە پێی هەمان ناوچە هەڵبژێرە.</p></section>
<section class="klesson-card"><h2>٢. وشەکانی کات</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>roj</td><td>ڕۆژ</td></tr><tr><td>şev</td><td>شەو</td></tr><tr><td>sibê</td><td>سبەی / بەیانیی داهاتوو</td></tr><tr><td>îro</td><td>ئەمڕۆ</td></tr><tr><td>doh</td><td>دوێنێ</td></tr><tr><td>niha</td><td>ئێستا</td></tr><tr><td>paşê</td><td>دواتر</td></tr><tr><td>zû</td><td>زوو</td></tr><tr><td>dereng</td><td>دواکەوتوو / درەنگ</td></tr><tr><td>hefte</td><td>هەفتە</td></tr><tr><td>meh</td><td>مانگ</td></tr><tr><td>sal</td><td>ساڵ</td></tr></tbody></table><p class="klesson-note">بۆ وشەکانی کات، فەرهەنگی کورمانجی بەکاربهێنە و واتای ڕستەیی بپشکنە؛ هەندێک وشە لە ڕستەی جیاوازدا واتای وردی جیاواز دەگرن.</p></section>
<section class="klesson-card"><h2>٣. نموونەی دەربڕین</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتای نزیک</th></tr></thead><tbody><tr><td>Îro duşem e.</td><td>ئەمڕۆ دووشەممەیە.</td></tr><tr><td>Ez sibê têm.</td><td>من سبەی دێم.</td></tr><tr><td>Em îro dixwînin.</td><td>ئێمە ئەمڕۆ دەخوێنین.</td></tr><tr><td>Ez niha amade me.</td><td>من ئێستا ئامادەم.</td></tr></tbody></table><p class="klesson-note">ئەم ڕستانە بۆ ڕاهێنانی سەرەتایین و پێویستە لەگەڵ سەرچاوەی ڕێزمانی و بەکارهێنانی قسەکەرانی کورمانجی پشکنین بکرێن، بە تایبەتی لە نووسینی کاتە داهاتوو و ڕستەی کرداریدا.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ناوی حەوت ڕۆژەکە بە کورمانجی بنووسە و لەبەریان بکە.</li><li>وشەکانی «ئەمڕۆ»، «دوێنێ»، «سبەی» و «ئێستا» بە کورمانجی بنووسە.</li><li>بە یارمەتی فەرهەنگ، ڕستەیەک دروست بکە کە ناوی ڕۆژێک و کاتێک تێدا بێت.</li><li>بەرنامەی خوێندنی خۆت بۆ سێ ڕۆژ بە کورمانجی بنووسە.</li><li>جیاوازیی واتای <em>roj</em> و <em>şev</em> لە نموونەی خۆتدا ڕوون بکەوە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Yari، <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English word list</a>.</li><li>Yari، <a href="https://yari.krd/learn/" target="_blank" rel="noopener">Learn Kurdish: guides for beginners</a>.</li><li>W. M. Thackston، <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>، <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>University of Arizona، <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>.</li></ol></section>',now()),
('kurmanji-course-1-lesson-17.html','kurmanji-course-1','کردار و کاتی ئێستای بنەڕەتی','<section class="klesson-card"><h2>١. بنەمای گشتی</h2><p>لە زۆرێک لە کردارە ئاساییەکانی کورمانجیدا، کاتی ئێستای ئاسایی بە پێشگرێکی <strong>di-</strong> لە پێش بنەی کردار و کۆتاییی کەسی دروست دەبێت. بەڵام هەموو کردارەکان بە شێوەیەکی یەکسان ڕێک ناخەون؛ کردارە نائاساییەکان و گۆڕانی دەنگی دەبێت بە جیا فێربکرێن.</p><div class="klesson-note">فۆرمۆڵی سەرەتایی: <strong>بکەر + di- + بنەی کردار + کۆتاییی کەسی</strong>. ئەمە ڕێسایەکی گشتییە، نە یاسایەکی بێ‌هەڵە بۆ هەموو کردارەکان.</div></section>
<section class="klesson-card"><h2>٢. نموونەی کردار: xwendin ـ خوێندنەوە</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody><tr><td>Ez dixwînim.</td><td>من دەخوێنمەوە.</td></tr><tr><td>Tu dixwînî.</td><td>تۆ دەخوێنیتەوە.</td></tr><tr><td>Ew dixwîne.</td><td>ئەو دەخوێنێتەوە.</td></tr><tr><td>Em dixwînin.</td><td>ئێمە دەخوێنینەوە.</td></tr><tr><td>Hûn dixwînin.</td><td>ئێوە دەخوێننەوە.</td></tr><tr><td>Ew dixwînin.</td><td>ئەوان دەخوێننەوە.</td></tr></tbody></table><p class="klesson-note">لە ڕستەی کۆمەڵدا <em>ew</em> دەتوانێت «ئەو» ی تاک یان «ئەوان»ی کۆ بگەیەنێت؛ کردار و بارودۆخی ڕستە یارمەتی دیاریکردنی واتا دەدەن.</p></section>
<section class="klesson-card"><h2>٣. چەند کردارێکی باو</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتای بنەڕەتی</th><th>نموونەی ئێستا</th></tr></thead><tbody><tr><td>xwendin</td><td>خوێندنەوە</td><td>Ez dixwînim.</td></tr><tr><td>çûn</td><td>چوون</td><td>Ez diçim.</td></tr><tr><td>kirin</td><td>کردن</td><td>Ez dikim.</td></tr><tr><td>nivîsîn</td><td>نووسین</td><td>Ez dinivîsim.</td></tr><tr><td>xwarin</td><td>خواردن</td><td>Ez dixwim.</td></tr></tbody></table><p>فۆڕمی کردار لە کاتی ئێستادا بە بنەی کردار و کۆتاییی کەسی پەیوەستە. لە کرداری نائاسایی و هەندێک فۆڕمی دەنگی‌گۆڕدا، پێویستە فەرهەنگ و ڕێزمانی تایبەت بپشکنرێت.</p></section>
<section class="klesson-card"><h2>٤. ڕیزبەندیی ڕستە</h2><p>ڕیزبەندیی باوی ڕستەی سادە لە کورمانجیدا زۆرجار <strong>بکەر + بەرکار + کردار</strong>ە؛ واتە کردار لە کۆتایی ڕستەدا دێت.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody><tr><td>Ez pirtûkekê dixwînim.</td><td>من کتێبێک دەخوێنمەوە.</td></tr><tr><td>Em kurdî hîn dibin.</td><td>ئێمە کوردی فێر دەبین.</td></tr><tr><td>Tu çi dinivîsî?</td><td>تۆ چی دەنووسیت؟</td></tr></tbody></table><p class="klesson-note">ڕیزبەندیی وشەکان دەتوانێت بۆ جەختکردنەوە بگۆڕێت؛ ئەم وانەیە تەنیا شێوەی بنەڕەتی پیشان دەدات.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>کرداری <em>xwendin</em> بۆ هەموو جێناوە کەسییەکان بنووسە.</li><li>ڕستەیەک بە <em>Ez dixwînim</em> دروست بکە و بەرکارێکی بۆ زیاد بکە.</li><li>فۆڕمی ئێستای کردارەکانی <em>çûn</em> و <em>kirin</em> لە فەرهەنگێکی باوەڕپێکراودا بپشکنە.</li><li>ڕستەیەکی کوردی بنووسە و هەوڵ بدە بە ڕیزبەندیی بکەر + بەرکار + کردار وەری بگێڕیتە کورمانجی.</li><li>لە ڕستەکاندا دیاری بکە کام بەش جێناوی بکەرە و کام بەش کردارە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish: syntax, pronouns and verbs</a>.</li><li>Thackston, W. M. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>, <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">grammar PDF</a>.</li><li>Kurdi School, <a href="https://kurdischool.com/grammar.html" target="_blank" rel="noopener">Kurmanji grammar, explained simply</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-18.html','kurmanji-course-1','نەفی لە ڕستەی سادەدا','<section class="klesson-card"><h2>١. نەفیی کردار لە کاتی ئێستادا</h2><p>لە کورمانجیی ستاندارددا، بۆ نەرێنی‌کردنی زۆرێک لە کردارەکانی کاتی ئێستا، پێشگری <strong>na-</strong> جێگای پێشگری ئەرێنی <strong>di-</strong> دەگرێتەوە. واتە پێشگرییەکان بە شێوەی ئاسایی لەگەڵ یەکتر کۆ نابنەوە.</p><table class="klesson-table"><thead><tr><th>ئەرێنی</th><th>نەرێنی</th><th>واتا</th></tr></thead><tbody><tr><td>Ez dixwînim.</td><td>Ez naxwînim.</td><td>من دەخوێنمەوە / ناخوێنمەوە.</td></tr><tr><td>Ez diçim.</td><td>Ez naçim.</td><td>من دەچم / ناچم.</td></tr><tr><td>Ez dinivîsim.</td><td>Ez nanivîsim.</td><td>من دەنووسم / نانووسم.</td></tr><tr><td>Ez dibêjim.</td><td>Ez nabêjim.</td><td>من دەڵێم / ناڵێم.</td></tr></tbody></table><p class="klesson-note">تێبینی: هەندێک کردار فۆڕمی تایبەت هەیە؛ بۆ نموونە «زانین» زۆرجار بە شێوەی <em>Ez nizanim</em> «نازانم» دێت، نەک فۆڕمێکی بە هەمان پێوانەی هەموو کردارەکان.</p></section>
<section class="klesson-card"><h2>٢. نەفیی زانیاری و بوون</h2><p>نەفیی کردار هەمیشە وەک نەفیی ناو یان ڕستەی ناوەکی دروست نابێت. بۆ نەفی‌کردنی هەندێک پەیوەندیی «بوون»، فۆڕمی تایبەتی کۆپولا یان پێکهاتەی <em>ne</em> بەکاردێت؛ لە نووسین و ڕستەدا جیاوازییەکە دەبێت بپارێزرێت.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody><tr><td>Ez nizanim.</td><td>من نازانم.</td><td>کرداری «زانین» فۆڕمی نەرێنی تایبەتی هەیە.</td></tr><tr><td>Ez ne mamosteyek im.</td><td>من مامۆستا نیم.</td><td>نەفی لە پێش بەشی ناوی/وەسفی ڕستە دێت؛ شێوەی نووسین بە پێی سەرچاوە دەتوانێت جیاواز بێت.</td></tr><tr><td>Ew li vir nîne.</td><td>ئەو لێرە نییە.</td><td>فۆڕمی «بوون/هەبوون» بە شێوەی تایبەت نەرێنی دەکرێت.</td></tr></tbody></table><p class="klesson-note">لە ڕستەی «بوون»دا فۆڕمەکانی کۆپولا لەگەڵ نەفیی کردار تێکەڵ مەکە. ئەم وانەیە تەنیا نموونەی ناساندنە؛ بۆ فۆڕمی وردی کۆپولا، سەرچاوەی ڕێزمانی بپشکنە.</p></section>
<section class="klesson-card"><h2>٣. نەفی لە فەرماندا</h2><p>لە فەرمانی نەرێنیدا، شێوەیەکی جیاواز لە نەفیی کاتی ئێستا بەکاردێت؛ لە زۆر فۆڕمدا <strong>ne-</strong> لە پێش کردار دەردەکەوێت.</p><table class="klesson-table"><thead><tr><th>فەرمانی ئەرێنی</th><th>فەرمانی نەرێنی</th><th>واتا</th></tr></thead><tbody><tr><td>Xwîne!</td><td>Nexwîne!</td><td>بخوێنەوە! / مەخوێنەوە!</td></tr><tr><td>Bike!</td><td>Neke!</td><td>بیکە! / مەیکە!</td></tr></tbody></table><p class="klesson-note">شێوەی فەرمان بەپێی بنەی کردار و جێناوی تاک/کۆ دەگۆڕێت. لە ڕێزمانی کورمانجیدا، <em>ne-</em> فۆڕمی باوی فەرمانی نەرێنییە؛ لە هەندێک سەرچاوە و بەکارهێنانی کۆنتر/ناوچەییدا شێوەی <em>me-</em>یش تۆمار کراوە، وەک <em>me-ke!</em> «مەیکە!». ئەم جیاوازییە نابێت بە یەکسانیی تەواو لەگەڵ هەموو شێوەزارەکاندا بخوێندرێتەوە. لە نموونەی فەرمانی کۆدا، لە فەرهەنگ یان ڕێزمانی پشت‌پێ‌بەستراو پشکنین بکە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ئەم ڕستانە نەرێنی بکە: <em>Ez dixwînim.</em>، <em>Ez diçim.</em>، <em>Ez dibêjim.</em></li><li>فۆڕمی نەرێنیی کرداری <em>zanîn</em> بنووسە و بڵێ بۆچی وەک هەموو کردارەکان نییە.</li><li>دوو ڕستەی ئەرێنی و دوو ڕستەی نەرێنی بە وشەی خۆت دروست بکە.</li><li>جیاوازیی نەفیی کردار لە کاتی ئێستا و فەرمانی نەرێنیدا بە وشەی خۆت ڕوون بکەوە.</li><li>هەموو نموونەکان لەگەڵ فەرهەنگێکی کورمانجی و سەرچاوەی ڕێزمانی بەراورد بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Songül Gündoğdu, “<a href="https://doi.org/10.1093/acprof:oso/9780190210434.003.0007" target="_blank" rel="noopener">Negation in Kurmanji</a>,” in <em>Affix Ordering Across Languages and Frameworks</em>, Oxford University Press, 2015.</li><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>, especially the discussion of verbal negation and dialect variation.</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-19.html','kurmanji-course-1','پرسیار و وشە پرسیارییەکان','<section class="klesson-card"><h2>١. وشە پرسیارییە سەرەتاییەکان</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>نموونە</th></tr></thead><tbody>
<tr><td>kî</td><td>کێ</td><td>Kî ye? — کێیە؟</td></tr>
<tr><td>çi</td><td>چی</td><td>Tu çi dixwazî? — تۆ چی دەوێت؟</td></tr>
<tr><td>li ku</td><td>لە کوێ</td><td>Tu li ku yî? — تۆ لە کوێیت؟</td></tr>
<tr><td>kengî</td><td>کەی</td><td>Tu kengî têyî? — تۆ کەی دێیت؟</td></tr>
<tr><td>çima</td><td>بۆچی</td><td>Tu çima dereng hatî? — بۆچی درەنگ هاتیت؟</td></tr>
<tr><td>çawa</td><td>چۆن</td><td>Tu çawa yî? — چۆنیت؟</td></tr>
<tr><td>çiqas</td><td>چەند / تا چەند</td><td>Ev çiqas e? — ئەمە چەندە؟</td></tr>
<tr><td>kîjan</td><td>کام</td><td>Kîjan pirtûk? — کام کتێب؟</td></tr>
</tbody></table><p class="klesson-note">شێوە و واتای هەندێک وشەی پرسیاری بە پێی ڕستە و شێوەزار دەگۆڕێت. بۆ فۆڕمی نووسینی ورد و بەکارهێنانی ڕێزمانی، فەرهەنگ و ڕێزمانی کورمانجی بەکاربهێنە.</p></section>
<section class="klesson-card"><h2>٢. پرسیاری بەڵێ/نەخێر</h2><p>پرسیاری بەڵێ/نەخێر ئەو پرسیارەیە کە وەڵامەکەی زۆرجار «بەڵێ» یان «نەخێر»ە. لە کورمانجی، نیشانەی پرسیار و دەنگی پرسیاری لە قسەدا یارمەتی دەدەن؛ لە نووسینیش نیشانەی <strong>؟</strong> یان <strong>?</strong> لە کۆتایی ڕستە دەنووسرێت. بۆ هەندێک جۆری پرسیار، پێکهاتە و ڕێکخستنی وشەکان گرنگە.</p><table class="klesson-table"><thead><tr><th>ڕستە</th><th>واتا</th></tr></thead><tbody><tr><td>Tu baş î?</td><td>باشیت؟</td></tr><tr><td>Tu kurdî dizanî?</td><td>کوردی دەزانیت؟</td></tr><tr><td>Ew li malê ye?</td><td>ئەو لە ماڵە؟</td></tr></tbody></table><p class="klesson-note">نموونەکان بۆ ناساندنی جۆری پرسیارن. لە قسەی سروشتیدا، ڕێکخستنی ڕستە و دەنگدان دەتوانێت بە پێی بارودۆخ و شێوەزار جیاواز بێت.</p></section>
<section class="klesson-card"><h2>٣. پرسیاری کراوە</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody><tr><td>Tu li ku dijî?</td><td>تۆ لە کوێ دەژیت؟</td></tr><tr><td>Navê te çi ye?</td><td>ناوی تۆ چییە؟</td></tr><tr><td>Tu kengî dixebitî?</td><td>تۆ کەی کار دەکەیت؟</td></tr><tr><td>Tu çima kurdî hîn dibî?</td><td>بۆچی کوردی فێر دەبیت؟</td></tr><tr><td>Tu bi çi awayî hatî?</td><td>بە چ شێوەیەک هاتیت؟</td></tr></tbody></table><p>لە پرسیاری کراوەدا، وشەی پرسیاری زانیارییەکی دیاریکراو داوا دەکات؛ وەڵامەکە تەنیا «بەڵێ» یان «نەخێر» نییە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>واتای وشەکانی <em>kî</em>، <em>çi</em>، <em>li ku</em>، <em>kengî</em> و <em>çima</em> بنووسە.</li><li>سێ پرسیاری بەڵێ/نەخێر بە کورمانجی دروست بکە.</li><li>پرسیارێک بە وشەی <em>kî</em> و پرسیارێک بە <em>kîjan</em> بنووسە و جیاوازییان ڕوون بکەوە.</li><li>لەسەر بنەمای نموونەکان، پرسیارێک لە هاوڕێیەکی خەیاڵی بکە و وەڵامێکی گونجاوی بنووسە.</li><li>ڕستەکان لەگەڵ فەرهەنگ و سەرچاوەی ڕێزمانی پشکنە؛ بە تایبەتی جێگای وشەی پرسیاری و شێوەی کردار.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>.</li><li>W. M. Thackston, <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li><li>University of Arizona, Iranian Languages, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish: grammar and language description</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-20.html','kurmanji-course-1','ڕیزبەندی وشەکان لە ڕستەدا','<section class="klesson-card"><h2>١. ڕیزبەندیی بنەڕەتی</h2><p>لە ڕستەی سادەی کورمانجی، ڕیزبەندیی بێ‌نیشان و باو زۆرجار <strong>بکەر + بەرکار + کردار (SOV)</strong>ە. ئەمە واتە کردار زۆرجار لە کۆتایی ڕستەدا دێت. بەڵام ئەم ڕیزە ڕێسایەکی ڕەق نییە؛ جەختکردنەوە، جۆری کردار، زانیاریی کۆن و نوێ، و شێوەزار دەتوانن ڕیزبەندی بگۆڕن.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>شیکردنەوە</th><th>واتا</th></tr></thead><tbody><tr><td>Ez nan dixwim.</td><td>Ez (بکەر) + nan (بەرکار) + dixwim (کردار)</td><td>من نان دەخۆم.</td></tr><tr><td>Tu pirtûkê dixwînî.</td><td>Tu (بکەر) + pirtûkê (بەرکار) + dixwînî (کردار)</td><td>تۆ کتێبەکە دەخوێنیتەوە.</td></tr><tr><td>Em kurdî hîn dibin.</td><td>Em (بکەر) + kurdî (بەرکار/ناوەڕۆک) + hîn dibin (کردار)</td><td>ئێمە کوردی فێر دەبین.</td></tr></tbody></table><p class="klesson-note">لە نموونەکاندا، فۆڕمی بەرکار و ڕێکخستنی وشەکان لەگەڵ کردار و حاڵەتی ڕێزمانی پەیوەندییان هەیە. لە کردارە تێپەڕەکانی ڕابردوودا، ڕێکخستنی حاڵەت و هاوڕێککەوتنی کردار دەتوانێت ئاڵۆزتر بێت.</p></section>
<section class="klesson-card"><h2>٢. ڕستەی بێ بەرکار</h2><p>هەموو ڕستەکان بەرکاریان نییە. لە کردارە تێنەپەڕەکاندا، ڕستە دەتوانێت بە بکەر و کردار تەواو بێت.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>پێکهاتە</th><th>واتا</th></tr></thead><tbody><tr><td>Zarok radizê.</td><td>بکەر + کردار</td><td>منداڵەکە دەخەوێت.</td></tr><tr><td>Ew diçe.</td><td>بکەر + کردار</td><td>ئەو دەچێت.</td></tr><tr><td>Em li malê dimînin.</td><td>بکەر + تەواوکەر + کردار</td><td>ئێمە لە ماڵ دەمێنینەوە.</td></tr></tbody></table><p>تەواوکەری شوێن، کات و شێواز دەتوانێت لە پێش کردار بێت، بەڵام شوێنی وردی بە پێی جۆری دەربڕین دەگۆڕێت.</p></section>
<section class="klesson-card"><h2>٣. گۆڕینی ڕیزبەندی بۆ جەختکردنەوە</h2><p>بۆ جەختکردنەوە لەسەر بەشێک لە ڕستە، ئەو بەشە دەتوانرێت بخرێتە پێشەوە. ئەم گۆڕانە واتای پراگماتیکی ڕستە دەگۆڕێت و نابێت هەموو ڕیزبەندییەکان وەک یەکسان و بێ‌جیاوازی لێک بدرێنەوە.</p><table class="klesson-table"><thead><tr><th>ڕستە</th><th>ڕوونکردنەوە</th></tr></thead><tbody><tr><td>Ez vê pirtûkê dixwînim.</td><td>ڕستەی بنەڕەتی: من ئەم کتێبە دەخوێنمەوە.</td></tr><tr><td>Vê pirtûkê, ez dixwînim.</td><td>بە جەختکردنەوە لەسەر «ئەم کتێبە»؛ لە نووسین پێویستە کۆنتێکست ڕوون بێت.</td></tr></tbody></table><p class="klesson-note">نموونەی جەختکردنەوە ڕێنمایییەکی فێرکارییە؛ بۆ بەکارهێنانی سروشتی و هەڵسەنگاندنی ڕێزمانی، بە سەرچاوەی ڕێزمانی و قسەکەری کورمانجی پشکنینی بکە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>لە ڕستەی <em>Ez nan dixwim</em> بکەر، بەرکار و کردار دیاری بکە.</li><li>ڕستەیەک دروست بکە کە تەنیا بکەر و کردار تێدا بێت.</li><li>ڕستەیەک بە بکەر + بەرکار + کردار بنووسە و بە هێما پێکهاتەکانی دیاری بکە.</li><li>هەوڵ بدە بە جەختکردنەوە لەسەر بەرکار ڕیزبەندی بگۆڕیت؛ پاشان بڵێ جەختەکە لەسەر کام بەشە.</li><li>جیاوازیی نێوان ڕیزبەندیی بنەڕەتی و گۆڕینی ڕیزبەندی بۆ مەبەستی قسەکردن ڕوون بکەوە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>, especially syntax and alignment.</li><li>University of Manchester, <a href="https://kurdish.humanities.manchester.ac.uk/about-kurdish/general-structural-characteristics/" target="_blank" rel="noopener">General structural characteristics of Kurdish</a>.</li><li>MELL, <a href="https://mell.am/languages/kmr/grammar/gtp-a37b42a35632e0f6b9c4" target="_blank" rel="noopener">Kurmanji compound verbs and basic word order</a> (grammar guide; treat as supplementary).</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-21.html','kurmanji-course-1','هاوەڵناو و وەسفکردن','<section class="klesson-card"><h2>١. هاوەڵناو چییە؟</h2><p>هاوەڵناو وشەیەکە کە تایبەتمەندی، دۆخ، ڕەنگ، قەبارە یان خاسیەتێکی ناو دەردەخات؛ وەک «گەورە»، «ڕەش» یان «باش». لە کورمانجی، هاوەڵناوی وەسفی زۆرجار دوای ناو دێت، نەک پێش ناو. ئەم خاڵە لە ڕیزبەندیی وشەکاندا جیاوازییەکی گرنگە.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody><tr><td>bajarê mezin</td><td>شارە گەورەکە؛ واتا بە کۆنتێکست دیاری دەبێت</td><td>ناوی بێ نیشانەی نەناسراوی <em>-ek</em> + ئیزافەی نێر + هاوەڵناو؛ بۆ واتای «شارێکی گەورە» نموونەی <em>bajar-ek-î mezin</em> بەکار هاتووە.</td></tr><tr><td>maleke biçûk</td><td>ماڵێکی بچووک</td><td>نمونەی فێرکاری بۆ ناو و هاوەڵناو.</td></tr><tr><td>pirtûka nû</td><td>کتێبی نوێ</td><td>پێکهاتەی ئیزافە؛ فۆڕمی ئیزافە دەبێت لەگەڵ پێکهاتەکە بگونجێت.</td></tr></tbody></table><p class="klesson-note">لە کورمانجیدا پەیوەندیی ناو و هاوەڵناو زۆرجار بە <strong>ئیزافە (ezafe)</strong> دەبەسترێت. فۆڕمی ئیزافە بە ڕەگەز، ژمارە و حاڵەتی ناو و پێکهاتەی ڕستە پەیوەستە؛ بۆیە نابێت یەک کۆتایی بۆ هەموو ناوەکان بەکاربهێنرێت.</p></section>
<section class="klesson-card"><h2>٢. ڕەنگ و تایبەتمەندی</h2><p>هاوەڵناو دەتوانێت ڕەنگ، قەبارە، تەمەن، هەڵسەنگاندن یان دۆخ وەسف بکات. لە خشتەکەدا وشەکان بە شێوەی فێرکاری هاتوون؛ کاتێک دەخرێنە ناو دەستەواژەی ناوی، پێویستە ئیزافە و حاڵەتی ڕێزمانی بپشکنرێت.</p><table class="klesson-table"><thead><tr><th>هاوەڵناو</th><th>واتا</th><th>جۆری وەسف</th></tr></thead><tbody><tr><td>mezin</td><td>گەورە</td><td>قەبارە</td></tr><tr><td>biçûk</td><td>بچووک</td><td>قەبارە</td></tr><tr><td>nû</td><td>نوێ</td><td>تەمەن/دۆخ</td></tr><tr><td>kevn</td><td>کۆن</td><td>تەمەن/دۆخ</td></tr><tr><td>baş</td><td>باش</td><td>هەڵسەنگاندن</td></tr><tr><td>reş</td><td>ڕەش</td><td>ڕەنگ</td></tr><tr><td>spî</td><td>سپی</td><td>ڕەنگ</td></tr></tbody></table></section>
<section class="klesson-card"><h2>٣. ناو + ئیزافە + هاوەڵناو</h2><p>لە زۆر پێکهاتەی ناوی کورمانجی، ناو لە سەرەتا دێت و هاوەڵناو لە دوای ئەوە. ئیزافەی پەیوەندیی نێوانیان نیشان دەدات و فۆڕمەکەی بە پێی ڕەگەز و ژمارەی ناو دەگۆڕێت.</p><table class="klesson-table"><thead><tr><th>پێکهاتە</th><th>شیکردنەوە</th></tr></thead><tbody><tr><td>bajar-ek-î mezin</td><td>شار + نیشانەی نەناسراوی + ئیزافەی نێر + گەورە؛ نموونەیەکی زانستیی سەرچاوە.</td></tr><tr><td>kum-ên reş</td><td>کڵاوەکان + ئیزافەی کۆ + ڕەش؛ هاوەڵناو دوای ناوەکە دێت.</td></tr></tbody></table><p>فۆڕمی سەرەوە لە ڕێزمانی کورمانجییەوە وەرگیراوە. ئەگەر ناوەکە دیارخەر، خاوەندار یان ژمارەی هەبێت، ڕیز و فۆڕمی ئیزافە دەتوانێت گۆڕانکاریی تێدا بکات.</p></section>
<section class="klesson-card"><h2>٤. وەسفکردن لە ڕستەدا</h2><p>هاوەڵناو دەتوانێت لە ناو دەستەواژەی ناویدا ناوێک وەسف بکات، یان لە ڕستەیەکدا بە شێوەی پێشبینی/هەواڵی خاسیەتێک بدات. ئەم دوو بەکارهێنانە یەک شت نین و نابێت ڕێزمانیان تێکەڵ بکرێت.</p><ul><li><strong>لە دەستەواژەی ناویدا:</strong> هاوەڵناو بە ئیزافەوە پەیوەندی بە ناوەکەوە دەبەستێت.</li><li><strong>لە ڕستەی هەواڵیدا:</strong> پێکهاتەی ناو + هاوەڵناو/هەواڵی خاسیەت بە شێوەی ڕێزمانی تایبەتی ڕستەکە دەردەکەوێت.</li></ul><p class="klesson-note">بۆ ڕستەی هەواڵی، نموونەکان لە پێناوی ئەم وانەیەدا بەبێ پشتگیریی ڕێزمانیی ورد زیاد نەکراون؛ لە وانەکانی داهاتوودا دەتوانرێت بە سەرچاوەی تایبەت بە کردار و ڕستەی هەواڵی فراوان بکرێت.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>لە پێکهاتەی <em>bajarê mezin</em> ناو و هاوەڵناو دیاری بکە.</li><li>پێنج هاوەڵناوی کورمانجی بنووسە و واتای کوردییان دیاری بکە.</li><li>جیاوازیی نێوان وەسفکردنی ناو لە دەستەواژەدا و وەسفکردن لە ڕستەدا ڕوون بکەوە.</li><li>بۆ نموونەی <em>bajar-ek-î mezin</em> ڕۆڵی ئیزافە و هاوەڵناو باس بکە.</li><li>بە سەرچاوەی وانەکە بپشکنە بۆچی هاوەڵناو زۆرجار دوای ناو دێت.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>, section 2.3, “The structure of the NP” and ezafe construction.</li><li>University of Arizona, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — syntax, nouns and ezafe</a>.</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-22.html','kurmanji-course-1','بەراوردکردنی تایبەتمەندییەکان','<section class="klesson-card"><h2>١. سێ پلەی هاوەڵناو</h2><p>هاوەڵناو دەتوانێت خاسیەتێک بەبێ بەراورد باس بکات، دوو شت بەراورد بکات، یان شتێک وەک بەرزترین/زۆرترین لە گروپێکدا دیاری بکات. ئەمانە بە شێوەی ئەرێنی، بەراوردی و زۆرترین پلە ناسراون.</p><table class="klesson-table"><thead><tr><th>پلە</th><th>کورمانجی</th><th>واتا</th></tr></thead><tbody><tr><td>ئەرێنی</td><td>mezin</td><td>گەورە</td></tr><tr><td>بەراوردی</td><td>mezintir</td><td>گەورەتر</td></tr><tr><td>زۆرترین پلە</td><td>herî mezin / mezintirîn</td><td>گەورەترین</td></tr></tbody></table><p class="klesson-note">بۆ زۆرترین پلە، دوو شێوەی باو هەن: <em>herî + هاوەڵناو</em>، وەک <em>herî mezin</em>؛ هەروەها پاشگری <em>-tirîn</em>یش بەکاردێت. جیاوازیی گرنگ لە ڕیزبەندییە: فۆڕمی <em>herî</em> پێش هاوەڵناو دێت، بەڵام فۆڕمی <em>-tirîn</em> وەک <em>mezintirîn bajar</em> پێش ناوی وەسفکراو دێت. فۆڕمی بەراوردی <em>meztir</em>یش لە سەرچاوەی ڕێزمانی کورمانجیدا لەگەڵ <em>mezintir</em> وەک فۆڕمێکی جێگرەوە تۆمار کراوە.</p></section>
<section class="klesson-card"><h2>٢. بەراورد بە زیادکردنی -tir</h2><p>ڕێگایەکی باوی دروستکردنی پلەی بەراوردی، زیادکردنی پاشگرەی <strong>-tir</strong>ە بۆ هاوەڵناو. پێویستە فۆڕمی وشەکە لە ڕێزمانێکی باوەڕپێکراودا بپشکنرێت، چونکە هەندێک وشە گۆڕانی فۆنۆلۆژی یان فۆڕمی تایبەتیان هەیە.</p><table class="klesson-table"><thead><tr><th>ئەرێنی</th><th>بەراوردی</th><th>واتا</th></tr></thead><tbody><tr><td>baş</td><td>baştir</td><td>باش → باشتر</td></tr><tr><td>mezin</td><td>mezintir / meztir</td><td>گەورە → گەورەتر؛ فۆڕمی بەکارهاتوو بە پێی سەرچاوە پشکنین بکە.</td></tr><tr><td>biçûk</td><td>biçûktir</td><td>بچووک → بچووکتر</td></tr><tr><td>dirêj</td><td>dirêjtir</td><td>درێژ → درێژتر</td></tr></tbody></table><p>لە ڕستەی بەراوردیدا، <em>ji</em> زۆرجار پێش ئەو کەس یان شتە دێت کە بەراوردی پێوە دەکرێت.</p><p><strong>Meyrem ji birayê xwe mezintir e.</strong><br>مەریەم لە براکەی گەورەترە.</p></section>
<section class="klesson-card"><h2>٣. زۆرترین پلە و کەمتر بوون</h2><table class="klesson-table"><thead><tr><th>فۆڕم</th><th>واتا</th><th>بەکارهێنان</th></tr></thead><tbody><tr><td>herî baş</td><td>باشترین</td><td>زۆرترین پلە بە <em>herî</em></td></tr><tr><td>herî mezin</td><td>گەورەترین</td><td>زۆرترین پلە بە <em>herî</em></td></tr><tr><td>kêmtir</td><td>کەمتر</td><td>کەمتر بوونی خاسیەت</td></tr><tr><td>zêdetir</td><td>زیاتر</td><td>زیاتر بوونی ڕادە یان بڕ</td></tr></tbody></table><p class="klesson-note">شێوەی <em>herî baş</em> و <em>herî mezin</em> وەک نموونەی فێرکاری بەکارهاتوون. شێوەی -tirîn لە هەندێک سەرچاوەدا هەیە، بەڵام نابێت بەبێ سەرچاوە و بەبێ تێبینیی شێوەزاری بڵێین لە هەموو ناوچەکاندا یەکسانە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>شێوەی بەراوردیی <em>baş</em>، <em>biçûk</em> و <em>dirêj</em> بنووسە.</li><li>ڕستەیەک بە <em>ji</em> دروست بکە کە دوو شت بەراورد بکات.</li><li>بە <em>herî</em> دەستەواژەیەک بۆ «باشترین» دروست بکە.</li><li>جیاوازیی نێوان پلەی بەراوردی و زۆرترین پلە ڕوون بکەوە.</li><li>بۆ هەر نموونەیەک، سەرچاوەکە بنووسە و فۆڕمی شێوەزاریی بەکارهاتوو دیاری بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Hasan Karacan &amp; Hewa Salam Khalid (2016), <a href="https://dergipark.org.tr/en/pub/ijoks/article/259420" target="_blank" rel="noopener"><em>Adjectives in Kurdish language: Comparison between dialects</em></a>, International Journal of Kurdish Studies 2(2), DOI: 10.21600/ijks.76230.</li><li><a href="https://ezdixan.de/en/wiki/grammatik" target="_blank" rel="noopener">Êzdîxan — Grammar Tables</a>, section “Adjective Comparison” (supplementary description of Kurmanji forms).</li><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>.</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-23.html','kurmanji-course-1','ناو و دیارخەرەکان','<section class="klesson-card"><h2>١. ناوی ناسراو و نەناسراو</h2><p>لە کورمانجیدا، وەک هەندێک زمان، ناو بە هۆی نیشانەیەکی جێگیر لە کۆتایی ناوەکەوە بە شێوەی گشتی وەک «ناوی ناسراو» ناناسرێتەوە. زانینی ئەوەی ناوەکە ناسراوە، نەناسراوە، گشتییە یان لە کۆنتێکستدا دیارە، بە مانا و بەکارهێنانی ڕستەوە پەیوەستە. لە بەرامبەردا، نیشانەی نەناسراوی <em>-ek</em> بەکاردێت.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody><tr><td>gund</td><td>گوند / گوندەکە</td><td>فۆڕمی ڕاستەوخۆی نێر؛ بە کۆنتێکست مانا دیاری دەبێت.</td></tr><tr><td>gundek</td><td>گوندێک</td><td>ناو + نیشانەی نەناسراوی -ek.</td></tr><tr><td>jin</td><td>ژن / ژنەکە</td><td>فۆڕمی بنەڕەتیی ناوی مێ.</td></tr><tr><td>jinek</td><td>ژنێک</td><td>ناو + نیشانەی نەناسراوی -ek.</td></tr></tbody></table><p class="klesson-note">«ناسراو» لێرە مەبەستی دیاریکراوی واتاییە، نەک ئەوەی هەمیشە پاشگرێکی تایبەت هەبێت. کورمانجی بە شێوەی گشتی ئەلفوبێی نیشانەی definite article ـی وەک -aka/-akan لە سورانیدا نییە.</p></section>
<section class="klesson-card"><h2>٢. نیشانەی نەناسراوی و حاڵەتی ڕێزمانی</h2><p>ناوی نەناسراو دەتوانێت لە حاڵەتی ڕاستەوخۆ یان ناڕاستەوخۆدا بێت. لە کورمانجیدا فۆڕمی ناو بە پێی ڕەگەزی ڕێزمانی و حاڵەت دەگۆڕێت؛ بۆیە نابێت تەنیا -ek ببینین و بەوە فۆڕمی هەموو پێکهاتەکان یەکسان بزانین.</p><table class="klesson-table"><thead><tr><th>فۆڕم</th><th>شیکردنەوە</th><th>واتا</th></tr></thead><tbody><tr><td>gund-ek</td><td>نێر، ڕاستەوخۆ، نەناسراو</td><td>گوندێک</td></tr><tr><td>gund-ek-î</td><td>نێر، ناڕاستەوخۆ، نەناسراو</td><td>گوندێک (لە پێکهاتەی ناڕاستەوخۆدا)</td></tr><tr><td>jin-ek</td><td>مێ، ڕاستەوخۆ، نەناسراو</td><td>ژنێک</td></tr><tr><td>jin-ek-ê</td><td>مێ، ناڕاستەوخۆ، نەناسراو</td><td>ژنێک (لە پێکهاتەی ناڕاستەوخۆدا)</td></tr></tbody></table><p>ئەم جیاوازییە لە کاتی وەرگرتنی بەرکار، دوای هەندێک ئامرازی پەیوەندی، یان لە پێکهاتەی خاوەنداریدا گرنگ دەبێت. شوێنی ڕاستەقینەی فۆڕم لە ڕستەدا بە ڕێزمانی پێکهاتەکە دیاری دەکرێت.</p></section>
<section class="klesson-card"><h2>٣. دیارخەرە ئاماژەییەکان</h2><p>وشەکانی <em>ev</em> و <em>ew</em> بۆ ئاماژەکردن بە شت یان کەس بەکاردێن: بە شێوەی گشتی <em>ev</em> بۆ نزیک و <em>ew</em> بۆ دوور. لە بەکارهێنانی ناوەوە، پێکهاتەی تەواو بە پێی حاڵەت و ڕۆڵی ڕێزمانی دەگۆڕێت.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>کارکرد</th></tr></thead><tbody><tr><td>ev pirtûk</td><td>ئەم کتێبە</td><td>ئاماژەی نزیک</td></tr><tr><td>ew pirtûk</td><td>ئەو کتێبە</td><td>ئاماژەی دوور</td></tr><tr><td>ev jin</td><td>ئەم ژنە</td><td>ئاماژە بە ناو</td></tr></tbody></table><p class="klesson-note">ئەم خشتەیە فۆڕمی بنەڕەتیی ئاماژەیی پیشان دەدات؛ لە ڕستەی ڕاستەقینەدا دەتوانێت فۆڕمی ناو یان ئاماژەکە بگۆڕێت، بەتایبەتی لە حاڵەتی ناڕاستەوخۆدا.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>جیاوازیی نێوان <em>gund</em> و <em>gundek</em> ڕوون بکەوە.</li><li>فۆڕمی ڕاستەوخۆ و ناڕاستەوخۆی ناوی نێر و مێ لە خشتەکەدا بەراورد بکە.</li><li>بە <em>ev</em> و <em>ew</em> دوو دەستەواژە دروست بکە و واتایان بنووسە.</li><li>ڕوون بکەوە بۆچی کورمانجی و سورانی هەمان نیشانەی ناسراویان نییە.</li><li>لە ڕێزمانێکدا نموونەی زیاتر بدۆزەوە و فۆڕمی ناوەکە لەگەڵ حاڵەتی ڕێزمانییەکەی تۆمار بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>, especially Table 7: case and indefiniteness in Standard Kurmanjî.</li><li>University of Arizona, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>, sections “Nouns” and “Pronouns”.</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-24.html','kurmanji-course-1','خاوەنداری لە دەربڕینەکاندا','<section class="klesson-card"><h2>١. دوو ڕێگای باوی دەربڕینی خاوەنداری</h2><p>لە کورمانجی، خاوەنداری دەتوانرێت بە جێناوی خاوەنداری پێش ناو، یان بە پێکهاتەی ئیزافە و دەستەواژەی خاوەندار دیاری بکرێت. فۆڕمی جێناو و پێکهاتەکە بە پێی ڕەگەز، ژمارە و حاڵەتی ڕێزمانی دەگۆڕێت.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody><tr><td>pirtûka min</td><td>کتێبەکەی من</td><td>ناو + ئیزافە + جێناوی خاوەنداری.</td></tr><tr><td>pirtûka te</td><td>کتێبەکەی تۆ</td><td>te: خاوەنداریی کەسی دووەم لەم پێکهاتەیەدا.</td></tr><tr><td>pirtûka wî</td><td>کتێبەکەی ئەو (نێر)</td><td>wî بۆ خاوەنداریی نێر لەم پێکهاتەیەدا.</td></tr><tr><td>pirtûka wê</td><td>کتێبەکەی ئەو (مێ)</td><td>wê بۆ خاوەنداریی مێ لەم پێکهاتەیەدا.</td></tr><tr><td>pirtûka me / we / wan</td><td>کتێبەکەی ئێمە / ئێوە / ئەوان</td><td>فۆڕمی خاوەنداری لەگەڵ کۆنتێکستدا بخوێنەوە.</td></tr></tbody></table><p class="klesson-note">ئەمانە نموونەی دەستەواژەی ناویین. لە ڕستەی تەواودا فۆڕمی ئیزافە و ناو دەتوانێت بە پێی ڕەگەز و حاڵەتی ڕێزمانی بگۆڕێت؛ هەموو فۆڕمەکان بە یەک ڕێسا ناگونجێن.</p></section>
<section class="klesson-card"><h2>٢. جێناوەکانی خاوەنداری</h2><p>لە دەستەواژەی ناوی، جێناوەکانی وەک <em>min, te, wî, wê, me, we, wan</em> دەتوانن خاوەندار دیاری بکەن. ئەمانە هەمان شت نین لەگەڵ جێناوە سەربەخۆکانی بکەر، وەک <em>ez</em> و <em>tu</em>.</p><table class="klesson-table"><thead><tr><th>جێناوی سەربەخۆ</th><th>فۆڕمی خاوەنداری</th><th>واتا</th></tr></thead><tbody><tr><td>ez</td><td>min</td><td>من / ـی من</td></tr><tr><td>tu</td><td>te</td><td>تۆ / ـی تۆ</td></tr><tr><td>ew (نێر)</td><td>wî</td><td>ئەو / ـی ئەو (نێر)</td></tr><tr><td>ew (مێ)</td><td>wê</td><td>ئەو / ـی ئەو (مێ)</td></tr><tr><td>em</td><td>me</td><td>ئێمە / ـی ئێمە</td></tr><tr><td>hûn</td><td>we</td><td>ئێوە / ـی ئێوە</td></tr><tr><td>ew (کۆ)</td><td>wan</td><td>ئەوان / ـی ئەوان</td></tr></tbody></table><p>ئەم خشتەیە پەیوەندییەکی فێرکاری نێوان فۆڕمەکان پیشان دەدات؛ بەکارهێنانی وردی جێناوی خاوەنداری بە پێی پێکهاتەی ڕستە و حاڵەتی ڕێزمانی دەگۆڕێت.</p></section>
<section class="klesson-card"><h2>٣. ئیزافەی خاوەنداری و ئیزافەی ئازاد «yê / ya / yên»</h2><p>بۆ دەربڕینی خاوەنداری، ئیزافە دەتوانێت خاوەن بە ناوەکەوە ببەستێتەوە؛ بەڵام «yê / ya / yên» لە هەموو کۆنتێکستێکدا واتای «خاوەنداری» نادات. لە کورمانجیی ستاندارددا، ئیزافەی ئازاد دەتوانێت بە واتای «ئەوەی...» یان «ئەوانەی...» بەکاربهێنرێت و فۆڕمەکەی بە ڕەگەز و ژمارەی ئەو ناوەی جێی دەگرێتەوە پەیوەستە.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody><tr><td>birayê min ê mezin</td><td>برا گەورەترەکەی من</td><td>پێکهاتەی ئیزافە؛ نموونەی سەرچاوەی ڕێزمانی.</td></tr><tr><td>yê spî</td><td>ئەوە سپییە (نێر)</td><td>ئیزافەی ئازاد، تاکی نێر.</td></tr><tr><td>ya te</td><td>ئەوەی تۆ (مێ)</td><td>ئیزافەی ئازاد، تاکی مێ.</td></tr><tr><td>yên mezin</td><td>ئەوانە گەورانەن</td><td>ئیزافەی ئازاد، کۆ.</td></tr></tbody></table><p class="klesson-note">لە سەرچاوەی Haig و Öpengin، نموونەکانی <em>yê spî</em>، <em>ya te</em> و <em>yên mezin</em> وەک ئیزافەی ئازاد/ئاماژەیی ڕوون کراونەتەوە. فۆڕمی ئیزافە لە پێکهاتەی ئیزافەدا بە ڕەگەز و ژمارەی ناوی سەرەکی پەیوەستە؛ بۆیە نابێت هەموو فۆڕمەکان بە یەک ڕێسا یەکسان بکرێن.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>واتای <em>pirtûka min</em> و <em>pirtûka wê</em> بنووسە.</li><li>جێناوی سەربەخۆی <em>tu</em> بە فۆڕمی خاوەنداریی پەیوەندیدارەوە بەراورد بکە.</li><li>بە <em>pirtûk</em> و جێناوی <em>me</em> دەستەواژەی خاوەنداری دروست بکە.</li><li>جیاوازیی نێوان جێناوی بکەر و جێناوی خاوەنداری ڕوون بکەوە.</li><li>بە سەرچاوەی وانەکە پشکنین بکە بۆچی ئیزافەی ناوی خاوەندار لەگەڵ ڕەگەز و حاڵەتدا دەگۆڕێت.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>, sections on pronouns, case and the noun phrase.</li><li>University of Arizona, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>, pronouns and noun phrase.</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>',now()),
('kurmanji-course-1-lesson-25.html','kurmanji-course-1','حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ','<section class="klesson-card"><h2>١. حاڵەت چییە؟</h2><p>حاڵەتی ڕێزمانی شێوەیەکە کە پەیوەندیی ناو یان جێناو بە ڕۆڵی لە ڕستەدا پیشان دەدات. لە کورمانجیدا جیاوازیی نێوان حاڵەتی ڕاستەوخۆ (<em>direct</em>) و ناڕاستەوخۆ (<em>oblique</em>) گرنگە؛ بە تایبەتی لە جێناوەکان، بەرکاری کردارە تێپەڕەکانی ئێستا، دوای ئامرازی پەیوەندی، خاوەنداری و ڕستەی ڕابردووی تێپەڕدا.</p><p class="klesson-note">ناوی «ڕاستەوخۆ/ناڕاستەوخۆ» لێرە ناوی دوو حاڵەتی ڕێزمانیی کورمانجییە، نەک تەنیا مانای ئاساییی وشەکانی «ڕاستەوخۆ» و «ناڕاستەوخۆ».</p></section>
<section class="klesson-card"><h2>٢. گۆڕانی ناو بە پێی حاڵەت</h2><p>فۆڕمی حاڵەتی ناو بە پێی ڕەگەزی ڕێزمانی، ژمارە و نیشانەی نەناسراوی دەگۆڕێت. لە نموونەی ستانداردی خوارەوەدا، ناوی نێری تاک زۆرجار لە حاڵەتی ڕاستەوخۆدا بێ کۆتاییی دیارە، بەڵام ناوی مێ و ناوی نەناسراو دەتوانن کۆتاییی دیار هەبێت.</p><table class="klesson-table"><thead><tr><th>ڕاستەوخۆ</th><th>ناڕاستەوخۆ</th><th>واتا</th></tr></thead><tbody><tr><td>gund</td><td>gund-î</td><td>گوند (نێری تاک، ناسراو)</td></tr><tr><td>gund-ek</td><td>gund-ek-î</td><td>گوندێک (نێری تاک، نەناسراو)</td></tr><tr><td>jin</td><td>jin-ê</td><td>ژن (مێی تاک، ناسراو)</td></tr><tr><td>jin-ek</td><td>jin-ek-ê</td><td>ژنێک (مێی تاک، نەناسراو)</td></tr><tr><td>mirov</td><td>mirov</td><td>پیاو/مرۆڤ (هەندێک فۆڕمی نێری تاک، بەبێ نیشانەی ڕووکەشی)</td></tr><tr><td>mirov-ek</td><td>mirov-ek-î</td><td>مرۆڤێک (نێری تاک، نەناسراو)</td></tr></tbody></table><p class="klesson-note">خشتەکە لەسەر ڕێزمانی ستاندارد دامەزراوە؛ هەندێک شێوەزار فۆڕمی ناوەکان یان گۆڕانی دەنگی بنەڕەت جیاواز دەردەخەن. بۆ ناوە تایبەتەکان و ناوی نێری تاکی گشتی، نیشانەی ڕووکەشی ڕەنگە نەردرکێت.</p></section>
<section class="klesson-card"><h2>٣. جێناوە ڕاستەوخۆ و ناڕاستەوخۆکان</h2><p>جێناوە سەربەخۆکانیش دوو کۆمەڵە فۆڕمیان هەیە. لە ڕستەی ئێستادا، جێناوی ڕاستەوخۆ زۆرجار بکەرە؛ فۆڕمی ناڕاستەوخۆ لە بەرکار، دوای ئامرازی پەیوەندی و لە دەربڕینی خاوەنداریدا دەردەکەوێت. لە ڕابردووی کردارە تێپەڕەکاندا، ئەم دابەشبوونە گرنگترە و پەیوەندی بە سیستەمی ئەرجەتیڤی کورمانجییەوە هەیە.</p><table class="klesson-table"><thead><tr><th>ڕاستەوخۆ</th><th>ناڕاستەوخۆ</th><th>کەس</th></tr></thead><tbody><tr><td>ez</td><td>min</td><td>من</td></tr><tr><td>tu</td><td>te</td><td>تۆ</td></tr><tr><td>ew</td><td>wî / wê</td><td>ئەو (فۆڕمی ناڕاستەوخۆ بە ڕەگەز جیا دەبێتەوە)</td></tr><tr><td>em</td><td>me</td><td>ئێمە</td></tr><tr><td>hûn</td><td>we</td><td>ئێوە</td></tr><tr><td>ew</td><td>wan</td><td>ئەوان</td></tr></tbody></table></section>
<section class="klesson-card"><h2>٤. حاڵەت لە ڕستەی ئێستا و ڕابردوودا</h2><p>لە ڕستەی ئێستای تێپەڕدا، بکەر زۆرجار لە حاڵەتی ڕاستەوخۆ و بەرکار لە ناڕاستەوخۆدا دێت:</p><p><strong>Ez wî mirovî dibînim.</strong><br>من ئەو پیاوە دەبینم.</p><p>لە ڕستەی ڕابردووی تێپەڕدا، کورمانجی ڕێکخستنی ئەرجەتیڤی بەکاردەهێنێت: بکەری ڕێزمانی زۆرجار لە حاڵەتی ناڕاستەوخۆیە و بەرکار لە حاڵەتی ڕاستەوخۆدا دێت.</p><p><strong>Min ew dît.</strong><br>من ئەوم بینی.</p><p class="klesson-note">ئەم نموونانە بنەڕەتیین. لە ڕستەی ڕابردووی تێپەڕدا کردار بە پێی بەرکار ڕێکدەکەوێت، نەک بە پێی بکەر؛ بۆیە ئەم سیستەمە لە ڕستەی ئێستا جیاوازە.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>جیاوازیی نێوان <em>gund</em> و <em>gund-î</em> لە ڕووی حاڵەتی ڕێزمانی ڕوون بکەوە.</li><li>فۆڕمە ڕاستەوخۆ و ناڕاستەوخۆکانی <em>ez/min</em> و <em>tu/te</em> لەبەر بکە.</li><li>لە ڕستەی <em>Ez wî mirovî dibînim</em> بکەر و بەرکار دیاری بکە.</li><li>لە ڕستەی <em>Min ew dît</em> ڕۆڵی <em>min</em> و <em>ew</em> باس بکە.</li><li>بە وشەی خۆت ڕوون بکەوە بۆچی ڕابردووی کردارە تێپەڕەکان لە کورمانجیدا سیستەمی جیاوازی حاڵەت هەیە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>, Table 7 and sections on case and ergativity.</li><li>University of Arizona, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>, noun case, pronouns and past tense.</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-26.html','kurmanji-course-1','پێداچوونەوە و هەڵسەنگاندنی کۆتایی','<section class="klesson-card"><h2>١. پێداچوونەوەی ڕێنووس و خوێندنەوە</h2><p>لە ئەلفبێی لاتینیی کورمانجیدا جیاوازیی نێوان پیتە تایبەتەکان گرنگە. بە تایبەتی، <em>c/ç</em>، <em>s/ş</em>، <em>i/î</em> و <em>u/û</em> نابێت بە یەک شت بخوێندرێنەوە.</p><table class="klesson-table"><thead><tr><th>پیت/وشە</th><th>واتا یان تێبینی</th></tr></thead><tbody><tr><td>çak</td><td>باش</td></tr><tr><td>şaş</td><td>هەڵە</td></tr><tr><td>dil</td><td>دڵ</td></tr><tr><td>îro</td><td>ئەمڕۆ</td></tr><tr><td>roj</td><td>ڕۆژ؛ تێبینی: ڕێنووسی ستاندارد «r» و «rr» لە هەندێک وشەدا جیاوازی دەردەخات.</td></tr></tbody></table></section>
<section class="klesson-card"><h2>٢. پێداچوونەوەی وشە و ڕستە</h2><p>بە وشەی ناسراو ڕستەیەکی کورت دروست بکە. لە ڕستەی سادەدا، ڕیزبەندیی باو زۆرجار بکەر + بەرکار + کردارە، بەڵام هەموو ڕستەیەک بەرکاری نییە و جەختکردنەوە دەتوانێت ڕیزبەندی بگۆڕێت.</p><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th><th>بابەت</th></tr></thead><tbody><tr><td>Ez nan dixwim.</td><td>من نان دەخۆم.</td><td>ڕیزبەندیی ڕستە</td></tr><tr><td>Tu çawa yî?</td><td>تۆ چۆنی؟</td><td>پرسیار</td></tr><tr><td>Ez naxwînim.</td><td>من ناخوێنمەوە.</td><td>نەفی</td></tr><tr><td>Ez wî mirovî dibînim.</td><td>من ئەو پیاوە دەبینم.</td><td>حاڵەتی ناڕاستەوخۆ</td></tr><tr><td>Min ew dît.</td><td>من ئەوم بینی.</td><td>ڕابردووی تێپەڕ و ئەرجەتیڤی</td></tr></tbody></table><p class="klesson-note">لە وانەکانی کۆرسدا نموونەی فێرکاری بەکارهاتووە؛ بۆ نووسین یان گفتوگۆی فەرمی، فۆڕمی وشە و ڕستە بە ڕێزمان و فەرهەنگی باوەڕپێکراو پشکنین بکە، چونکە هەندێک شێوەزار جیاوازییان هەیە.</p></section>
<section class="klesson-card"><h2>٣. تاقیکردنەوەی کورت</h2><ol><li>جیاوازیی دەنگ و نووسینی <em>c</em> و <em>ç</em> باس بکە.</li><li>واتای <em>min</em> و <em>ez</em> بنووسە و جیاوازیی ڕێزمانییان ڕوون بکەوە.</li><li>لە ڕستەی <em>Ez nan dixwim</em> بکەر، بەرکار و کردار دیاری بکە.</li><li>نموونەیەک بە <em>herî</em> بۆ زۆرترین پلەی هاوەڵناو بنووسە.</li><li>نموونەیەک بە <em>-ek</em> دروست بکە بۆ ناوی نەناسراو.</li><li>ڕستەیەکی ئەرێنی بنووسە و دواتر بە شێوەی نەفی دایڕێژە.</li><li>بە وشەی خۆت جیاوازیی نێوان حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ ڕوون بکەوە.</li><li>لە ڕستەی ڕابردووی تێپەڕدا ڕۆڵی بکەر و بەرکار دیاری بکە.</li></ol></section>
<section class="klesson-card"><h2>٤. خشتەی خۆهەڵسەنگاندن</h2><table class="klesson-table"><thead><tr><th>توانایی</th><th>خۆهەڵسەنگاندن</th></tr></thead><tbody><tr><td>ئەلفبێ و پیتە تایبەتەکان</td><td>☐ باشم ☐ پێویستم بە ڕاهێنانە</td></tr><tr><td>خوێندنەوە و نووسینی وشەی سادە</td><td>☐ باشم ☐ پێویستم بە ڕاهێنانە</td></tr><tr><td>جێناو، ژمارە و وشەی ڕۆژانە</td><td>☐ باشم ☐ پێویستم بە ڕاهێنانە</td></tr><tr><td>کردار، نەفی و پرسیار</td><td>☐ باشم ☐ پێویستم بە ڕاهێنانە</td></tr><tr><td>هاوەڵناو، ئیزافە و خاوەنداری</td><td>☐ باشم ☐ پێویستم بە ڕاهێنانە</td></tr><tr><td>حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ</td><td>☐ باشم ☐ پێویستم بە ڕاهێنانە</td></tr></tbody></table><p>ئەم خشتەیە بۆ خۆهەڵسەنگاندنە؛ نمرەی فەرمی یان پشتڕاستکردنەوەی توانایی نییە. ئەگەر لە بابەتێکدا دڵنیایت نییە، بگەڕێوە بۆ وانەی پەیوەندیدار و ڕاهێنانی زیاتر بکە.</p></section>
<section class="klesson-card"><h2>٥. سەرچاوە بنەڕەتییەکان</h2><ol><li>University of Arizona, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a> — ئەلفبێ، ڕێنووس، جێناو، حاڵەت، کردار و ڕێزمان.</li><li>Geoffrey Haig &amp; Ergin Öpengin, <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener"><em>Overview of Northern Kurdish (Kurmanjî)</em></a>.</li><li>W. M. Thackston, <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li><li>Yari, <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English Dictionary</a> — بۆ پشکنینی واتا و فۆڕمی وشەکان.</li></ol></section>',now()),
  ('kurmanji-course-2-lesson-01.html','kurmanji-course-2','مۆرفۆلۆجی و پێکهاتەی وشە','<section class="klesson-card"><h2>١. وشە و مۆرفیم</h2><p>وشە یەکەیەکی سەربەخۆی بەکارهێنانە؛ مۆرفیم بچووکترین یەکەی فۆڕم و واتای ڕێزمانی یان وشەسازییە. مۆرفیم هەمیشە وشەی سەربەخۆ نییە؛ هەندێک مۆرفیم وەک پاشگر بە وشەوە دەبەسترێت.</p></section><section class="klesson-card"><h2>٢. چەند ئاستی پشکنین</h2><p>لە پشکنینی وشەدا، پێویستە ڕەگ، مۆرفیمی وشەسازی و نیشانەی ڕێزمانی لێک جیا بکرێنەوە. هەموو بەشێکی دەنگی وشە بە خۆی مۆرفیم نییە؛ بڕیار دەبێت بە پشت‌بەستن بە بەراوردی شێوە و واتا بدرێت.</p></section><section class="klesson-card"><h2>٣. نموونەی پشکنین</h2><p>بۆ نموونە، لە کورمانجی‌دا پاشگری -ek دەتوانێت لە ناوی تاکدا نادیاری پیشان بدات؛ ئەمە نموونەیەکە لەوەی چۆن مۆرفیمێک کارکردێکی ڕێزمانی هەیە. لە وانەی ٤دا وردتر دەخوێندرێتەوە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">شێوە و کارکردی مۆرفیمەکان لە هەموو شێوەزارەکاندا بە تەواوی یەکسان نییە. لێکدانەوەی ئەم کۆرسە بە بنەمای کورمانجیی ستانداردە و جیاوازییەکان دەبێت بە سەرچاوەوە دیاری بکرێن.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>مۆرفۆلۆجی چی دەخوێنێتەوە؟</li><li>جیاوازی وشە و مۆرفیم چییە؟</li><li>بۆچی نابێت هەر بەشێکی دەنگی وشە بە مۆرفیم دابنرێت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-02.html','kurmanji-course-2','ڕەگ، پێشگر و پاشگر','<section class="klesson-card"><h2>١. ڕەگ و بنەڕەت</h2><p>لە پشکنینی مۆرفۆلۆژیدا، ڕەگ و بنەڕەت هەندێک جار بە مانای جیاواز بەکاردێن: ڕەگ یەکەی بنەڕەتییە، بەڵام بنەڕەت دەتوانێت فۆڕمێک بێت کە پاشگر یان پێشگر وەردەگرێت. لە توێژینەوەدا پێویستە پێناسەی بەکارهاتوو ڕوون بکرێتەوە.</p></section><section class="klesson-card"><h2>٢. پێشگر و پاشگر</h2><p>پێشگر لە پێش بنەڕەتەوە دێت و پاشگر لە دواوەیەوە. بۆ نموونە، -ek لە ناوی کورمانجی‌دا پاشگرێکی ناسراوە کە لە زۆر سیاقێکدا نادیاریی تاک نیشان دەدات؛ بەڵام نابێت بۆ هەر وشەیەک بە شێوەیەکی ئۆتۆماتیکی ئەم شیکردنەوەیە بەکاربهێنرێت.</p></section><section class="klesson-card"><h2>٣. شیکردنەوەی زانستی</h2><p>بۆ هەر وشەیەک، فۆڕمی بنەڕەت، مۆرفیمی زیادکراو و گۆڕانی واتایی یان ڕێزمانی بەڵگەدار بکە. ئەگەر بەشێک لە وشەکان بە بەراورد پشتگیری نەکرێت، بە پێشگری خەیاڵی یان پاشگری خەیاڵی دابنەنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">پێشگر و پاشگر تەنیا بە شوێنیان ناسراو ناکرێن؛ کارکردی ڕێزمانی و بەراوردی وشەکانیش پێویستە. نموونەکان بە بنەمای Thackston و Haig و Öpengin بخوێنەوە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ڕەگ چییە؟</li><li>جیاوازی پێشگر و پاشگر چییە؟</li><li>بۆچی پێویستە وشەکان بەراورد بکرێن؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-03.html','kurmanji-course-2','ناو، ڕەگەزی ڕێزمانی و ژمارە','<section class="klesson-card"><h2>١. ڕەگەزی ڕێزمانی</h2><p>لە کورمانجیی ستاندارددا جیاوازی نێر و مێ لە ناوی تاکدا هەیە. ڕەگەزی ڕێزمانی هەمیشە بە واتای سروشتیی نێر و مێ یەکسان نییە؛ پێویستە ڕەگەزی هەر ناوێک لە سەرچاوەی ڕێزمانی و لە ڕێککەوتنەکانی دەوروبەریدا بپشکنرێت.</p></section><section class="klesson-card"><h2>٢. تاک و کۆ</h2><p>ژمارە جیاوازی نێوان تاک و کۆ نیشان دەدات. لە کورمانجی‌دا شێوەکانی کۆ بە جۆری ناو و فۆڕمی ڕێزمانی پەیوەستن؛ بۆیە نابێت یاسایەکی تاک بۆ هەموو ناوەکان بگشتێندرێت.</p></section><section class="klesson-card"><h2>٣. پەیوەندی بە ڕێککەوتنەوە</h2><p>ڕەگەز و ژمارە لە پاشگری ئەزافەدا ڕەنگ دەدەنەوە. لە زۆر پێکهاتەی ناوی‌دا، فۆڕمی ئەزافە بە ڕەگەز و ژمارەی ناوی سەرەکی پەیوەستە، نەک تەنیا بە وشەی دواتر.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">لە شێوەزارەکانی کورمانجی‌دا جیاوازییەکانی ڕەگەز، ژمارە و فۆڕمی ناو هەن. خشتەی یاساکان دەبێت بە دیاریکردنی شێوەزار و سەرچاوە پێشکەش بکرێت.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ڕەگەزی ڕێزمانی چییە؟</li><li>ئایا ڕەگەزی ڕێزمانی هەمیشە ڕەگەزی سروشتی نیشان دەدات؟</li><li>ڕەگەز و ژمارە چ پەیوەندییەکیان بە ئەزافەوە هەیە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-04.html','kurmanji-course-2','ناوی دیار و نادیار؛ پاشگری -ek','<section class="klesson-card"><h2>١. نادیاری بە -ek</h2><p>لە نموونەی باوی کورمانجی‌دا gund ‘گوند’ و gundek ‘گوندێک’ بەراورد دەکرێن. -ek نیشانەی نادیاریی تاکە؛ لە شیکردنەوەی ورددا پێویستە فۆڕمی حاڵەتی ڕاستەوخۆ/ناڕاستەوخۆ و ئەزافەش لەبەرچاو بگیرێت.</p></section><section class="klesson-card"><h2>٢. ناوی بێ پاشگر</h2><p>ناوی بێ -ek هەمیشە بە واتای دیار نییە؛ بە پێی سیاق دەتوانێت ئاماژە بە شتێکی ناسراو، جۆرێک بە گشتی، یان شتێک کە لە گفتوگۆدا دیارە بکات. بۆیە پێویستە ڕستە و سیاق بخوێندرێتەوە.</p></section><section class="klesson-card"><h2>٣. حاڵەت و فۆڕمی نادیار</h2><p>لە ستانداردی کورمانجی‌دا شێوەی ناوی نادیار دەتوانێت لە حاڵەتی ناڕاستەوخۆدا نیشانەی زیاتر وەربگرێت؛ وەک gund-ek-î و jin-ek-ê لە خشتەی ڕێزمانی Haig و Öpengin. ئەم شێوەیەکان بۆ پیشاندانی سیستەمەکەن، نەک بۆ ئەوەی بێ سیاق لە هەموو ڕستەیەکدا بەکاربهێنرێن.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">Haig و Öpengin (2018) جیاوازی حاڵەتی ڕاستەوخۆ/ناڕاستەوخۆ و نادیاری لە خشتەی ناوەکاندا پیشان دەدەن. شێوەی هەر ناوێک بە ڕەگەز، حاڵەت و سیاقەوە پەیوەستە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پاشگری -ek زۆرجار چی نیشان دەدات؟</li><li>بۆچی ناوی بێ -ek هەمیشە دیار نییە؟</li><li>چۆن حاڵەت دەتوانێت فۆڕمی ناوی نادیار بگۆڕێت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-05.html','kurmanji-course-2','ئەزافە و پەیوەندیی ناو و هاوەڵناو','<section class="klesson-card"><h2>١. ئەزافە لەگەڵ هاوەڵناو</h2><p>هاوەڵناو زۆرجار دوای ناو دێت و بە ئەزافەوە بە ناوەکەوە دەبەسترێتەوە. نموونەی نووسراو لە Haig و Öpengin: bajar-ek-î mezin ‘شارێکی گەورە’. ئەم نموونەیە نادیاری، ئەزافە و هاوەڵناو لە یەک پێکهاتەدا نیشان دەدات.</p></section><section class="klesson-card"><h2>٢. ئەزافە لەگەڵ خاوەندار</h2><p>ئەزافە بۆ پەیوەستکردنی ناو بە خاوەندار یان ناوی دیکەش بەکاردێت. فۆڕمی ئەزافە لەگەڵ ڕەگەز و ژمارەی ناوی سەرەکی ڕێکدەکەوێت؛ پێویستە خاوەندار و سەرەناو لە یەکتر جیا بکرێنەوە.</p></section><section class="klesson-card"><h2>٣. ڕیزبەندیی پێکهاتە</h2><p>لە پێکهاتەی ناویی کورمانجی‌دا ناو دەتوانێت لەگەڵ دیارخەر، ژمارە، خاوەندار و هاوەڵناو بێت. ڕیزبەندی و فۆڕمی ئەزافە بە پێکهاتەی وردەوە دەگۆڕێت؛ نابێت یاسایەکی سادە بۆ هەموو پێکهاتەکان بەکاربهێنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">نموونەی bajar-ek-î mezin لە توێژینەوەی Haig و Öpengin هاتووە. فۆڕمەکانی ئەزافە لە شێوەزارەکاندا هەندێک جیاوازییان هەیە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ئەزافە چ ئەرکێکی ڕێزمانی هەیە؟</li><li>بۆچی فۆڕمی ئەزافە بە ناوی سەرەکی پەیوەستە؟</li><li>لە نموونەی bajar-ek-î mezin، -î چی پەیوەندییەک دروست دەکات؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-06.html','kurmanji-course-2','خاوەنداری و جێناوە خاوەندارییەکان','<section class="klesson-card"><h2>١. خاوەندار بە ئەزافە</h2><p>پێکهاتەی ئەزافە دەتوانێت پەیوەندیی خاوەنداری نیشان بدات. لە نموونەی Haig و Öpengin، mal-a me ‘ماڵی ئێمە’ پەیوەندیی نێوان ناو و جێناوی خاوەندار پیشان دەدات. فۆڕمی ئەزافە لەگەڵ ناوی سەرەکی پەیوەستە.</p></section><section class="klesson-card"><h2>٢. جێناوی خاوەنداری</h2><p>جێناوە خاوەندارییەکان لە سیاقە جیاوازەکاندا بەکاردێن و فۆڕمیان بە پێی کەس و ژمارە دەگۆڕێت. پێویستە جێناوی کەسیی سەربەخۆ لە فۆڕمی خاوەنداری و لە جێناوی ناو ڕستە جیا بکرێتەوە.</p></section><section class="klesson-card"><h2>٣. جێناوی خۆ (xwe)</h2><p>xwe جێناوێکی خۆگەڕە کە لە کورمانجی‌دا بە پێی کەس و ژمارە ناگۆڕێت. لە پێکهاتەیەکدا کە ئاماژەکەی بۆ هەمان بکەر بگەڕێتەوە، دەتوانێت ڕۆڵی خۆی هەبێت؛ بەڵام پەیوەندیی ئاماژەیی دەبێت لە ڕستەی تەواودا پشکنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">خاوەنداری تەنیا واتای «هی کێیە» نییە؛ پێکهاتەی ڕێزمانی و ڕێککەوتنی ئەزافەش بەشێکن لە شیکردنەوە. فۆڕمەکان بە پشت‌بەستن بە سەرچاوە پێشکەش کراون.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ئەزافە چۆن خاوەنداری دەردەبڕێت؟</li><li>جیاوازی جێناوی کەسی و خاوەنداری چییە؟</li><li>xwe لە چ جۆر سیاقێکدا بەکاردێت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
('kurmanji-course-2-lesson-07.html','kurmanji-course-2','جێناوە کەسییەکان و حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ','<section class="klesson-card"><h2>١. فۆڕمەکانی جێناوی کەسی</h2><p>لە کورمانجیی ستاندارددا فۆڕمە ڕاستەوخۆکان بریتین لە ez, tu, ew, em, hûn, ew؛ فۆڕمە ناڕاستەوخۆکانیش min, te, wî/wê, me, we, wan. ئەم دوو کۆمەڵەیە لە Haig و Öpengin (2018)دا بە شێوەی خشتە هاتوون.</p></section><section class="klesson-card"><h2>٢. حاڵەت و ئەرکی ڕستە</h2><p>حاڵەتی ناڕاستەوخۆ لە کورمانجی‌دا لە چەند ژینگەی ڕێزمانی دەردەکەوێت؛ بۆیە نابێت بە یاسای «هەمیشە بکەر ناڕاستەوخۆیە» یان «هەمیشە بەرکار ڕاستەوخۆیە» کورت بکرێتەوە. کات، جۆری کردار و پێکهاتەی ڕستە کاریگەرییان هەیە.</p></section><section class="klesson-card"><h2>٣. سیستەمی ڕابردوو</h2><p>لە ڕستەی ڕابردووی زۆرێک لە کردارە تێپەڕەکاندا، بکەر دەتوانێت بە فۆڕمی ناڕاستەوخۆ دەربکەوێت، لە کاتێکدا بەرکار بە شێوەیەکی دیکە ڕێکدەکەوێت. ئەمە بابەتی گرنگی سیستەمی حاڵەت و ergativity ـە و پێویستی بە شیکردنەوەی ڕستەی تەواو هەیە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">خشتەی جێناوەکان لە Haig و Öpengin (2018) و Thackston هەڵبژێردراوە. لە پشکنینی ڕستەی تایبەتدا کات و جۆری کردار دیاری بکە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>فۆڕمە ناڕاستەوخۆکانی ez، tu، ew چین؟</li><li>بۆچی حاڵەت تەنیا بە ئەرکی بکەر/بەرکار ناسراو ناکرێت؟</li><li>ڕابردووی کردارە تێپەڕەکان چ پەیوەندییەکیان بە حاڵەتی ناڕاستەوخۆوە هەیە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-08.html','kurmanji-course-2','کردار، ڕەگ، کەس و ژمارە','<section class="klesson-card"><h2>١. ڕەگی کردار</h2><p>بۆ شیکردنەوەی کردار، فۆڕمی بنەڕەتی و ڕەگی کردار بناسە؛ دواتر دیاری بکە چ نیشانەیەک کەس، ژمارە، کات یان ڕەوش دەردەخات. هەموو کردارەکان بە هەمان ڕێسا فۆڕم وەرناگرن.</p></section><section class="klesson-card"><h2>٢. کەس و ژمارە</h2><p>فۆڕمی کردار لە ڕستەدا لەگەڵ کەس و ژمارە پەیوەندی هەیە، بەڵام شێوازی ئەم پەیوەندییە بە کات و جۆری ڕستە دەگۆڕێت. جێناوی ئاشکرا هەموو جارێک بە مانای ئەوە نییە کە نیشانەی کەس لە کرداردا نییە.</p></section><section class="klesson-card"><h2>٣. تێپەڕی و ناتێپەڕی</h2><p>کرداری ناتێپەڕ زۆرجار بێ بەرکاری ڕاستەوخۆ بەکاردێت؛ کرداری تێپەڕ دەتوانێت بەرکاری ڕاستەوخۆ وەربگرێت. ئەم جیاوازییە گرنگە بۆ تێگەیشتن لە حاڵەت و ڕێککەوتن، بە تایبەتی لە ڕستە ڕابردووەکاندا.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ئەم وانەیە چوارچێوەی شیکردنەوە دەدات؛ بۆ خشتەی تەواوی فۆڕمەکانی کردار، سەرچاوەی ڕێزمانی بە پێی کردار و کات بخوێنەوە و فۆڕمی تایبەت بە گشتی مەکە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>لە شیکردنەوەی کرداردا چ زانیارییەکان دەبێت دیاری بکرێن؟</li><li>جیاوازی کردارە تێپەڕ و ناتێپەڕەکان چییە؟</li><li>بۆچی فۆڕمی کردار بە کات و جۆری ڕستەوە پەیوەستە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-09.html','kurmanji-course-2','کاتی ئێستا، ڕابردوو و داهاتوو','<section class="klesson-card"><h2>١. کاتی ئێستا</h2><p>لە کاتی ئێستادا، پێشگر و فۆڕمی کردار دەتوانن زانیاریی کات و ڕەوش بگەیەنن. بۆ نموونە، فۆڕمەکانی di- لە زۆر کردارەکاندا لە پێکهاتەی ئێستادا دەردەکەون؛ بەڵام کردارە تایبەتەکان فۆڕمی جیاوازیان هەیە.</p></section><section class="klesson-card"><h2>٢. کاتی ڕابردوو</h2><p>ڕابردوو یەک شێوەی سادە نییە: جیاوازی نێوان کردارە تێپەڕ و ناتێپەڕەکان و فۆڕمەکانی کردار لە ڕێکخستنی ڕستەدا کاریگەری هەیە. لە ڕستەی ڕابردووی کردارە تێپەڕەکاندا سیستەمی حاڵەت گرنگە.</p></section><section class="klesson-card"><h2>٣. داهاتوو و واتای کات</h2><p>واتای داهاتوو دەتوانێت بە پێکهاتەی کردار و وشەی یاریدەدەر دەرببڕدرێت؛ شێوەی بەکارهێنان بە سیاق و جۆری ڕستەوە پەیوەستە. لە شیکردنەوەدا فۆڕمی کردار لەگەڵ نیشانەکانی کات و سیاق بە یەکەوە بخوێنەوە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ئەم وانەیە پێشەکییە بۆ سیستەمی کات و ڕەوش. خشتەی پارادایمی تەواو پێویستی بە سەرچاوەی تایبەت و دیاریکردنی شێوەزار هەیە؛ لێرەدا فۆڕمی ناپشکنراو دروست نەکراوە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پێشگری di- لە زۆر کردارەکانی کاتی ئێستادا چ ڕۆڵێکی هەیە؟</li><li>بۆچی ڕابردووی کردارە تێپەڕەکان بە جیاوازی لە کردارە ناتێپەڕەکان دەخوێندرێتەوە؟</li><li>داهاتوو بۆچی نابێت بە یاسای پاشگری یەکسان کورت بکرێتەوە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-10.html','kurmanji-course-2','ڕستەی نەفی و پرسیاری','<section class="klesson-card"><h2>١. نەفیی کردار</h2><p>لە زۆر فۆڕمەکانی کاتی ئێستای کورمانجی‌دا، na- بۆ نەفی بەکاردێت و لە بەرامبەر di- دێت؛ بەڵام کردارە تایبەتەکان هەن، بۆیە یاساکە نابێت بەبێ پشکنین بۆ هەموو کردارەکان بگشتێندرێت.</p></section><section class="klesson-card"><h2>٢. نەفیی ڕستەی ناوەکی</h2><p>نەفیی ڕستەی ناوەکی و نەفیی کردار هەمیشە بە هەمان فۆڕم دروست نابن. فۆڕمی نەفی دەبێت بە پێی جۆری پێکهاتە و کردار بپشکنرێت.</p></section><section class="klesson-card"><h2>٣. پرسیاری بەڵێ/نەخێر و وشە پرسیاری</h2><p>پرسیاری بەڵێ/نەخێر دەتوانێت بە ئاواز و سیاق ناسرێتەوە؛ پرسیاری زانیاریییش وشەی پرسیاری وەک کێ، چی، لە کوێ یان کەی بەکار دەهێنێت. ڕیزبەندی وشەکان لە ڕستەی پرسیاریدا دەبێت بە پێی شێوەی ستاندارد و سیاق بپشکنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">فۆڕمەکانی نەفی و پرسیار لە کردارە جیاوازەکاندا بەراورد بکە؛ یاسایەکی گشتی لە نموونەی تاکەوە مەدەرهێنە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>na- لە زۆر فۆڕمەکانی کاتی ئێستادا چی دەکات؟</li><li>جیاوازی نەفیی کردار و ڕستەی ناوەکی چییە؟</li><li>دوو جۆری پرسیاری سەرەکی چین؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-11.html','kurmanji-course-2','ڕێکخستنی وشەکان و پێکهاتەی ڕستە','<section class="klesson-card"><h2>١. ڕستەی سادە</h2><p>بۆ شیکردنەوەی ڕستە، بکەر، کردار و ئەگەر هەبێت بەرکار دیاری بکە. دواتر بپشکنە ئایا کردار تێپەڕە یان ناتێپەڕە و حاڵەتی ناو و جێناوەکان چییە.</p></section><section class="klesson-card"><h2>٢. پێکهاتەی ناوی</h2><p>ناو دەتوانێت لەگەڵ دیارخەر، ژمارە، خاوەندار و هاوەڵناو پێکهاتەیەکی فراوان دروست بکات. لە کورمانجی‌دا هاوەڵناو و خاوەندار زۆرجار بە ئەزافەوە بە ناوە سەرەکییەکە دەبەسترێن.</p></section><section class="klesson-card"><h2>٣. زانیاریی نوێ و جەخت</h2><p>لە گفتوگۆدا هەندێک بەش بۆ جەختکردن یان گونجاندن لەگەڵ زانیاریی پێشوو دەکرێت بگوازرێنەوە. بۆیە نابێت هەر جیاوازییەکی ڕیزبەندی بە هەڵەی ڕێزمانی دابنرێت؛ سیاق و شێوازی بەکارهێنان پێویستن.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ڕیزبەندیی بکەر–بەرکار–کردار وەک ڕێڕەوی بنەڕەتی فێر دەکرێت، نەک وەک یاسایەکی بێ‌استثنا. جیاوازییە زمانییەکان و جەخت لەبەرچاو بگرە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>لە شیکردنەوەی ڕستەدا چ ئەرکەکان دیاری دەکرێن؟</li><li>ئەزافە لە پێکهاتەی ناوی‌دا چ ڕۆڵێک هەیە؟</li><li>بۆچی ڕیزبەندیی وشەکان هەمیشە بێ‌استثنا نییە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-12.html','kurmanji-course-2','پێداچوونەوە و تاقیکردنەوەی کۆتایی','<section class="klesson-card"><h2>١. پێداچوونەوەی مۆرفۆلۆجی</h2><p>مۆرفیم و ڕەگ بناسە؛ پێشگر و پاشگر لە بەراوردی فۆڕمەکاندا دیاری بکە. پاشگری -ek لە ناوی تاکدا زۆرجار نادیاری دەردەخات، بەڵام سیاق و حاڵەت لە شیکردنەوەدا گرنگن.</p></section><section class="klesson-card"><h2>٢. پێداچوونەوەی پێکهاتەی ناوی</h2><p>ڕەگەز و ژمارەی ناو لەگەڵ ئەزافە و هاوەڵناو پشکنە. لە پێکهاتەی خاوەنداریدا، ناوی سەرەکی و خاوەندار لە یەکتر جیا بکەوە.</p></section><section class="klesson-card"><h2>٣. پێداچوونەوەی کردار و ڕستە</h2><p>فۆڕمی جێناوی ڕاستەوخۆ و ناڕاستەوخۆ جیا بکەوە؛ کات و تێپەڕی/ناتێپەڕی کردار دیاری بکە. نەفی و پرسیار لە ڕستەی تەواودا بپشکنە و ڕیزبەندی وشەکان بەبێ لەبەرچاوگرتنی سیاق هەڵنەسەنگێنە.</p></section><section class="klesson-card"><h2>٤. ڕاهێنانی کۆتایی</h2><p>ڕستەیەکی کورمانجی هەڵبژێرە و (١) ناو و کردارەکان دیاری بکە، (٢) فۆڕمی جێناو و حاڵەت بنووسە، (٣) ئەزافە و پاشگرەکان شیکەرەوە، (٤) کات و نەفی/پرسیار پشکنە، (٥) هەر بڕیارێک بە سەرچاوە و سیاق پشتگیری بکە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ئەم پێداچوونەوەیە تاقیکردنەوەی زانیارییە، نەک جێگرەوەی ڕاهێنانی لەگەڵ دەقی سەرچاوە. هەر نموونەیەکی نوێ پێش بەکارهێنانی فێرکاری دەبێت بە سەرچاوەی ڕێزمانی بەراورد بکرێت.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پاشگری -ek، ئەزافە و حاڵەت چ جیاوازییەکیان هەیە؟</li><li>بۆچی فۆڕمی جێناو بە کات و جۆری ڕستە پەیوەستە؟</li><li>لە شیکردنەوەی زانستیی ڕستەدا چۆن سەرچاوە بەکار دەهێنیت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey, and Öpengin, Ergin. (2018). “Northern Kurdish (Kurmanjî).” In <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a> · <a href="https://multicast.aspra.uni-bamberg.de/data/pubs/Haig2018_Northern-Kurdish_Kurmanji.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نموونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now())
ON CONFLICT (lesson_key) DO UPDATE
SET title=EXCLUDED.title, content_html=EXCLUDED.content_html, updated_at=now();

CREATE OR REPLACE FUNCTION public.can_read_lesson_content(p_course_id text, p_lesson_key text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  uid uuid := auth.uid();
  lesson_order text[];
  lesson_index integer;
BEGIN
  IF uid IS NULL THEN RETURN false; END IF;
  IF public.is_site_owner() THEN RETURN true; END IF;

  -- Defense in depth: an authenticated user must be enrolled before this
  -- RPC reports any lesson as readable. The lesson_content RLS policy also
  -- enforces enrollment, but the RPC should not report access on its own.
  IF NOT EXISTS (
    SELECT 1
    FROM public.enrollments e
    WHERE e.user_id = uid
      AND e.course_id = p_course_id
      AND e.status IN ('active','completed')
  ) THEN
    RETURN false;
  END IF;

  IF p_course_id = 'phonetics-phonology-kurdik' THEN
    SELECT array_agg('course-2-' || lpad(n::text,2,'0') || '.html' ORDER BY n)
      INTO lesson_order FROM generate_series(1,32) AS g(n);
  ELSIF p_course_id = 'kurmanji-course-1' THEN
    SELECT array_agg('kurmanji-course-1-lesson-' || lpad(n::text,2,'0') || '.html' ORDER BY n)
      INTO lesson_order FROM generate_series(1,26) AS g(n);
  ELSIF p_course_id = 'kurmanji-course-2' THEN
    SELECT array_agg('kurmanji-course-2-lesson-' || lpad(n::text,2,'0') || '.html' ORDER BY n)
      INTO lesson_order FROM generate_series(1,12) AS g(n);
  ELSIF p_course_id = 'orthography-kurdik' THEN
    lesson_order := ARRAY[
      '017.html','018.html','019.html','020.html','021.html','022.html','023.html','024.html',
      '025.html','026.html','027.html','028.html','029.html','030.html','031.html','032.html',
      '033.html','034.html','035.html','036.html','037.html','038.html','039.html','040.html',
      '041.html','042.html','043.html','044.html','046.html','047.html','048.html','049.html',
      '050.html','051.html','045.html','052.html','053.html','054.html','055.html','056.html',
      '057.html','058.html'
    ];
  ELSE
    RETURN false;
  END IF;

  lesson_index := array_position(lesson_order, p_lesson_key);
  IF lesson_index IS NULL THEN RETURN false; END IF;
  IF lesson_index = 1 THEN RETURN true; END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.lesson_progress lp
    WHERE lp.user_id = uid
      AND lp.course_id = p_course_id
      AND lp.lesson_key = lesson_order[lesson_index - 1]
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.can_read_lesson_content(text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_read_lesson_content(text,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.complete_lesson(p_course_id text, p_lesson_key text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  uid uuid := auth.uid();
  total_count integer;
  completed_count integer := 0;
  new_status text := 'active';
  lesson_order text[];
  lesson_index integer;
  previous_key text;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  IF NOT public.is_site_owner() AND NOT EXISTS (
    SELECT 1 FROM auth.users u
    WHERE u.id = uid AND (u.email_confirmed_at IS NOT NULL OR u.phone_confirmed_at IS NOT NULL)
  ) THEN RAISE EXCEPTION 'EMAIL_NOT_VERIFIED'; END IF;

  IF p_course_id = 'phonetics-phonology-kurdik' THEN
    SELECT array_agg('course-2-' || lpad(n::text,2,'0') || '.html' ORDER BY n)
      INTO lesson_order FROM generate_series(1,32) AS g(n);
  ELSIF p_course_id = 'kurmanji-course-1' THEN
    SELECT array_agg('kurmanji-course-1-lesson-' || lpad(n::text,2,'0') || '.html' ORDER BY n)
      INTO lesson_order FROM generate_series(1,26) AS g(n);
  ELSIF p_course_id = 'kurmanji-course-2' THEN
    SELECT array_agg('kurmanji-course-2-lesson-' || lpad(n::text,2,'0') || '.html' ORDER BY n)
      INTO lesson_order FROM generate_series(1,12) AS g(n);
  ELSIF p_course_id = 'orthography-kurdik' THEN
    lesson_order := ARRAY[
      '017.html','018.html','019.html','020.html','021.html','022.html','023.html','024.html',
      '025.html','026.html','027.html','028.html','029.html','030.html','031.html','032.html',
      '033.html','034.html','035.html','036.html','037.html','038.html','039.html','040.html',
      '041.html','042.html','043.html','044.html','046.html','047.html','048.html','049.html',
      '050.html','051.html','045.html','052.html','053.html','054.html','055.html','056.html',
      '057.html','058.html'
    ];
  ELSE
    RAISE EXCEPTION 'COURSE_NOT_FOUND';
  END IF;

  lesson_index := array_position(lesson_order, p_lesson_key);
  IF lesson_index IS NULL THEN RAISE EXCEPTION 'INVALID_LESSON'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.enrollments e
    WHERE e.user_id = uid AND e.course_id = p_course_id AND e.status IN ('active','completed')
  ) AND NOT public.is_site_owner() THEN
    RAISE EXCEPTION 'NOT_ENROLLED';
  END IF;

  IF lesson_index > 1 AND NOT public.is_site_owner() THEN
    previous_key := lesson_order[lesson_index - 1];
    IF NOT EXISTS (
      SELECT 1 FROM public.lesson_progress lp
      WHERE lp.user_id = uid AND lp.course_id = p_course_id AND lp.lesson_key = previous_key
    ) THEN RAISE EXCEPTION 'PREVIOUS_LESSON_REQUIRED'; END IF;
  END IF;

  INSERT INTO public.lesson_progress(user_id, course_id, lesson_key, completed_at)
  VALUES (uid, p_course_id, p_lesson_key, now())
  ON CONFLICT (user_id, course_id, lesson_key)
  DO UPDATE SET completed_at = EXCLUDED.completed_at;

  SELECT c.total_lessons INTO total_count FROM public.courses c WHERE c.id = p_course_id;

  IF p_course_id IN ('phonetics-phonology-kurdik','kurmanji-course-1','kurmanji-course-2') THEN
    SELECT count(*) INTO completed_count
    FROM public.lesson_progress lp
    WHERE lp.user_id = uid AND lp.course_id = p_course_id
      AND lp.lesson_key = ANY(lesson_order);
  ELSE
    -- Preserve the existing grouped completion accounting for the orthography course.
    SELECT count(*) INTO completed_count
    FROM public.lesson_progress lp
    WHERE lp.user_id = uid AND lp.course_id = p_course_id
      AND lp.lesson_key = ANY(ARRAY[
        '017.html','018.html','019.html','020.html','021.html','022.html','023.html',
        '024.html','025.html','026.html','027.html','028.html','029.html','030.html',
        '031.html','032.html','033.html','034.html','035.html','036.html','037.html'
      ]);

    IF (SELECT count(*) FROM public.lesson_progress lp WHERE lp.user_id=uid AND lp.course_id=p_course_id
      AND lp.lesson_key=ANY(ARRAY['038.html','039.html','040.html','041.html','042.html','043.html','044.html']))=7
      THEN completed_count := completed_count + 1; END IF;
    IF (SELECT count(*) FROM public.lesson_progress lp WHERE lp.user_id=uid AND lp.course_id=p_course_id
      AND lp.lesson_key=ANY(ARRAY['046.html','047.html','048.html','049.html','050.html','051.html']))=6
      THEN completed_count := completed_count + 1; END IF;
    IF EXISTS(SELECT 1 FROM public.lesson_progress lp WHERE lp.user_id=uid AND lp.course_id=p_course_id AND lp.lesson_key='045.html')
      THEN completed_count := completed_count + 1; END IF;
    IF (SELECT count(*) FROM public.lesson_progress lp WHERE lp.user_id=uid AND lp.course_id=p_course_id
      AND lp.lesson_key=ANY(ARRAY['052.html','053.html','054.html','055.html','056.html','057.html']))=6
      THEN completed_count := completed_count + 1; END IF;
    IF EXISTS(SELECT 1 FROM public.lesson_progress lp WHERE lp.user_id=uid AND lp.course_id=p_course_id AND lp.lesson_key='058.html')
      THEN completed_count := completed_count + 1; END IF;
  END IF;

  IF completed_count >= total_count THEN
    new_status := 'completed';
    UPDATE public.enrollments SET status='completed', completed_at=COALESCE(completed_at, now())
    WHERE user_id=uid AND course_id=p_course_id;
  END IF;

  RETURN jsonb_build_object('status', new_status, 'completed_count', completed_count,
    'total_lessons', total_count, 'course_completed', (new_status='completed'));
END;
$function$;

-- Preserve/confirm the intended RPC exposure.
REVOKE ALL ON FUNCTION public.complete_lesson(text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.complete_lesson(text,text) TO authenticated;

COMMIT;
